export const bcklSentences: Sentence[] = [
  {"id":"s_work_bckl_1_1","chapterId":"ch_work_bckl_1","text":"卷之一","sortOrder":1},
  {"id":"s_work_bckl_1_2","chapterId":"ch_work_bckl_1","text":"〈計戰〉第一","sortOrder":2},
  {"id":"s_work_bckl_1_3","chapterId":"ch_work_bckl_1","text":"凡用兵之道，以計為首。未戰之時，先料將之賢愚，敵之強弱，兵之眾寡，地之险易，糧之虛實。計料已審，然後出兵，無有不勝。法曰：「料敵製勝，計险厄遠近，上將之道也。」","sortOrder":3},
  {"id":"s_work_bckl_1_4","chapterId":"ch_work_bckl_1","text":"漢末，劉先主在襄陽，三往求計於諸葛亮。亮曰：「自董卓造逆以來，天下豪杰併起，跨州連郡者不可勝數。曹操比於袁紹，則名微而眾寡，然操遂能克紹，以弱為強者，非惟天時，抑亦人謀也。今操已擁百萬之眾，挟天子而令諸侯，此誠不可與爭鋒。孫權據有江東，已歷三世，國险而民附，賢能為之用，此可以為援而不可圖也。荆州北據漢、沔，利盡南海，東連吳、會，西通巴、蜀，此用武之國，而其主不能守。此殆天所以資將軍，將軍豈有意乎？益州险塞，沃野千里，天府之土，高祖因之以成帝業。劉璋暗弱，張魯在北，民殷國富而不知存恤，智能之士思得明君。將軍既帝室之冑，信義著於四海，總攬英雄，思賢如渴，若跨有荆、益，保其巖阻，西和諸戎，南撫夷越，外結好孫權，內修政理；天下有变，則命一上將將荆州之軍以向宛、洛，將軍身帥益州之眾出於秦川，百姓孰敢不箪食壶漿以迎將軍者乎？誠如是，霸業可成，漢室可興矣。」先主曰：「善。」後果如其計。","sortOrder":4},
  {"id":"s_work_bckl_1_5","chapterId":"ch_work_bckl_1","text":"〈謀戰〉第二","sortOrder":5},
  {"id":"s_work_bckl_1_6","chapterId":"ch_work_bckl_1","text":"凡敵始有謀，我從而攻之，使彼計窮而屈服。法曰：「上兵伐謀。」","sortOrder":6},
  {"id":"s_work_bckl_1_7","chapterId":"ch_work_bckl_1","text":"春秋時，晉平公欲伐齊，使范昭往觀齊國之政。齊景公觴之。酒酣，范昭請君之樽酌。公曰：「寡人之樽進客。」范昭已飲，晏子撤樽，更為酌。范昭佯醉，不悅而起舞，謂太師曰：「我欲成周之樂，能為我奏，吾為舞之。」太師曰：「瞑臣不習。」范昭出，景公曰：「晉，大國也。來觀吾政，今子怒大國之使者，將奈何？」晏子曰：「范昭非陋於禮者，今將慚吾國，臣故不從也。」太師曰：「夫成周之樂，天子之樂也，惟人主舞之。今范昭人臣，而欲舞天子之樂，臣故不為也。」范昭歸報晉平公曰：「齊未可伐，臣欲辱其君，晏子知之；臣欲犯其禮，太師識之。」仲尼〔聞之〕曰：「不越樽俎之間，而折冲於千里之外，晏子之謂也。」","sortOrder":7},
  {"id":"s_work_bckl_1_8","chapterId":"ch_work_bckl_1","text":"〈間戰〉第三","sortOrder":8},
  {"id":"s_work_bckl_1_9","chapterId":"ch_work_bckl_1","text":"凡欲征伐，先用間諜，觇敵之眾寡、虛實、動靜，然後興師，則大功可立，戰無不勝。法曰：「無所不用間也。」","sortOrder":9},
  {"id":"s_work_bckl_1_10","chapterId":"ch_work_bckl_1","text":"周將韦叔裕，字孝宽，以德行守镇玉壁。孝宽善於撫御，能得人心，所遣間諜入齊者，皆為盡力。亦有齊人得孝宽賂金者，遙通書疏。故齊動靜，朝廷皆知之。齊相斛律光，字明月，賢而有勇，孝宽深忌之。參軍曲嚴頗知卜筮，謂孝宽曰：「來年東朝必大殺戮。」孝宽因令嚴作謠歌曰：「百升飛上天，明月照長安。」百升，斛也。又言：「高山不推自崩，槲木不扶自立。」令諜者多赉此文，遺之於鄴。祖孝征與光有隙，既聞，更润色之。明月卒以此見誅。周武帝聞光死，赦其境內，後大舉兵伐之，遂滅齊。","sortOrder":10},
  {"id":"s_work_bckl_1_11","chapterId":"ch_work_bckl_1","text":"〈選戰〉第四","sortOrder":11},
  {"id":"s_work_bckl_1_12","chapterId":"ch_work_bckl_1","text":"凡與敵戰，須要選揀勇將銳卒，使為先鋒，一則壮我志，一則挫敵威。法曰：「兵無選鋒曰北。」","sortOrder":12},
  {"id":"s_work_bckl_1_13","chapterId":"ch_work_bckl_1","text":"建安十二年，袁尚、熙奔上穀郡，〔引〕乌桓數入塞為害。曹操征之。夏五月，至無終；秋七月，大水，傍海道路不通。田畴請為乡导，操從之，率兵出盧龍塞，水潦，塞外道絕不通，乃堑山堙穀五百餘里，經白檀，歷平刚，涉鮮卑庭，東指柳城。未至二百里，虜方知之。尚、熙與蹋頓、遼西单於樓班、右北平单於能臣抵之等將數萬騎逆軍。八月，登白狼山，卒與虜遇，眾甚盛。操辎重在後，披甲者甚少，左右皆懼。操登高而望，見虜陣不整，乃縱兵击之，使張遼為先鋒，虜眾大潰。斬蹋頓及名王以下，胡、漢降者二十餘萬口。","sortOrder":13},
  {"id":"s_work_bckl_1_14","chapterId":"ch_work_bckl_1","text":"〈步戰〉第五","sortOrder":14},
  {"id":"s_work_bckl_1_15","chapterId":"ch_work_bckl_1","text":"凡步兵與車、騎戰者，必依丘陵、险阻、林木而戰則勝。若遇平易之道，須用拒馬槍為方陣，步兵在內。馬軍、步兵中分為駐队、戰队。駐队守陣，戰队出戰；戰队守陣，駐队出戰。敵攻我一面，則我兩哨出兵，從旁以掩之；敵攻我兩面，我分兵從後以捣之；敵攻我四面，我為圓陣，分兵四出以奋击之。敵若败走，以騎兵追之，步兵隨其後，乃必勝之法。法曰：「步兵與車、騎戰者，必依丘陵、险阻，如無险阻，令我士卒為行馬、蒺藜。」","sortOrder":15},
  {"id":"s_work_bckl_1_16","chapterId":"ch_work_bckl_1","text":"《五代史》：晉將周德威為盧龍節度使，恃勇不修邊備，遂失榆關之险。契丹每刍牧於營、平之間，陷新州，德威复取不克，奔歸幽州。契丹围之二百日，城中危困。李嗣源聞之，約李存勖，步騎七萬，會於易州救之。乃自易州北行，逾大房嶺，循涧而東。嗣源與養子從珂將三千騎為先鋒，進至山口，契丹以萬騎遮其前，將士失色。嗣源以百騎先進，免冑扬鞭，胡語謂契丹曰：「汝無故犯我疆埸，晉王命我將百萬騎眾，直抵西樓，滅汝种族。」因躍馬奋挝，三入其陣，斬契丹酋長一人。後軍齊進，契丹兵却，晉兵始得出。李存勖命步兵伐木為鹿角陣，人持一枝以成寨。契丹環寨而過，寨中萬弩齊發射之，流矢","sortOrder":16},
  {"id":"s_work_bckl_1_17","chapterId":"ch_work_bckl_1","text":"蔽日，契丹人馬死者塞道。將至幽州，契丹列陣以待之。存勖令步兵陣於後，戒勿先動。令羸兵曳柴、燃草而進，煙尘蔽天，契丹莫测其多少，因鼓入戰。存勖乃趨後陣，起而乘之，契丹遂大败，席卷其眾，自北山口遁去。俘斬其首級萬計，遂解幽州之围。","sortOrder":17},
  {"id":"s_work_bckl_1_18","chapterId":"ch_work_bckl_1","text":"〈騎戰〉第六","sortOrder":18},
  {"id":"s_work_bckl_1_19","chapterId":"ch_work_bckl_1","text":"凡騎兵與步兵戰者，若遇山林、险阻、陂泽之地，疾行急去，是必败之地，勿得與戰。欲戰，須得平易之地，進退無礙，戰則必勝。法曰：「易地則用騎。」","sortOrder":19},
  {"id":"s_work_bckl_1_20","chapterId":"ch_work_bckl_1","text":"《五代史》：唐莊宗救趙，與梁軍相拒於柏乡五里，營於野河北。晉兵少，梁將王景仁將兵雖多，而精銳者亦少。晉軍望之色動。周德威勉其眾曰：「此汴、宋佣，易败耳。」退而告之。〔莊宗曰：「梁兵甚銳，未可與爭，宜少退以待之。」〕莊宗曰：「吾提孤兵出千里，利在速戰。今若不乘势而急击之，使敵人知我之眾寡，則計無所施矣。」德威曰：「不然。趙人皆能城守而不能野戰；吾之取勝，利在騎兵。平原曠野，騎兵之所長也。今吾軍於河上，迫近營門，非吾用長之地也。」莊宗不悅，退臥帳中，諸將無敢入見者。德威乃謂監軍張承業曰：「王怒老將。不速戰者，非怯也。且吾兵少而臨賊營門，所恃者一水隔耳。使梁得舟筏渡河，吾無類矣。不如退軍高邑，誘敵出營，扰而勞之，可以策勝也。」承業入言曰：「德威老將知兵，願無忽其言。」莊宗遽起曰：「吾方思之耳。」已而，德威獲梁遊兵，問景仁何為？曰：「治舟數百，將以為浮梁。」德威乃與俱見莊宗","sortOrder":20},
  {"id":"s_work_bckl_1_21","chapterId":"ch_work_bckl_1","text":"，〔莊宗〕笑曰：「果如公所料。」乃退軍高邑。","sortOrder":21},
  {"id":"s_work_bckl_1_22","chapterId":"ch_work_bckl_1","text":"德威乃遣騎三百，扣梁營挑戰，自以劲兵三千繼之。景仁怒，悉以其軍出，與德威轉斗數十里，至於高南，兩軍皆陣。梁軍橫亘六、七里。莊宗策馬登高，望而喜曰：「平原淺草，可前可却，真吾製勝之地也。」乃使人告德威曰：「吾當為公〔先，公可繼進。〕」德威諫曰：「梁軍輕出，而遠來與吾轉戰，其來既速，必不暇赉糧糗；縱其能，亦不暇食。不及日午，人馬飢渴，其軍必退。退而击之，必獲勝焉。」至未、申時，梁軍中尘煙大起，德威鼓噪而進，梁軍大败。","sortOrder":22},
  {"id":"s_work_bckl_1_23","chapterId":"ch_work_bckl_1","text":"〈舟戰〉第七","sortOrder":23},
  {"id":"s_work_bckl_1_24","chapterId":"ch_work_bckl_1","text":"凡與敵戰於江湖之間，必有舟楫，須居上風、上流。上風者順風，用火以焚之；上流者隨势，使戰艦以冲之，則戰無不勝。法曰：「欲戰者，無迎水流。」","sortOrder":24},
  {"id":"s_work_bckl_1_25","chapterId":"ch_work_bckl_1","text":"春秋，吳子伐楚。楚令尹卜戰，不吉。司馬子魚曰：「我得上流，何故不吉？」遂戰，已巨艦冲突；吳軍势弱，遂至败績。","sortOrder":25},
  {"id":"s_work_bckl_1_26","chapterId":"ch_work_bckl_1","text":"〈車戰〉第八","sortOrder":26},
  {"id":"s_work_bckl_1_27","chapterId":"ch_work_bckl_1","text":"凡與步、騎戰於平原曠野，必須用偏箱、鹿角車為方陣，以戰則勝。所謂一則治力，一則前拒，一則整束部伍也。法曰：「廣地則用車軍。」","sortOrder":27},
  {"id":"s_work_bckl_1_28","chapterId":"ch_work_bckl_1","text":"晉涼州刺史楊欣，失羌戎之和，為虜所没。河西斷絕，帝每有西顧之忧，臨朝而叹曰：「誰能為我通涼州讨此虜者乎？」朝臣莫對。司馬督馬隆進曰：「陛下若能任臣，臣能平之。」帝曰：「若能滅賊，何為不任，顧卿方略何如耳！」隆曰：「陛下若能任臣，當聽臣自任。」帝曰：「雲何？」對曰：「臣請募勇士三千人，無問所從來，率之鼓行而西，禀陛下威德，丑類何足滅者！」帝許之，乃以隆為武威太守。隆募腰开弩三十六鈞，立標簡试，自旦至日中，得三千五百人。隆曰：「足矣。」隆於是率其眾西渡溫水，虜树機能等，以眾萬騎，或乘险以遏隆前，或設伏以截隆後。隆依八陣圖作偏箱車，地廣用鹿角車，路狹則為木屋施於車上，且戰且前，弓矢所及，應絃而倒。轉戰千里，殺傷以千數。隆到武威，虜大人萃跋韓、且萬能等，率萬餘眾歸。隆前後誅殺及降附者數萬。又率善戎、没骨能等，與树機能等戰，斬之，涼州遂平。","sortOrder":28},
  {"id":"s_work_bckl_1_29","chapterId":"ch_work_bckl_1","text":"〈信戰〉第九","sortOrder":29},
  {"id":"s_work_bckl_1_30","chapterId":"ch_work_bckl_1","text":"凡與敵戰，士卒蹈萬死一生之地，而無悔懼之心者，皆信令使然也。上好信以任誠，則下用情而無疑，故戰無不勝。法曰：「信則不欺。」","sortOrder":30},
  {"id":"s_work_bckl_1_31","chapterId":"ch_work_bckl_1","text":"三國魏明帝自征蜀，幸長安，遣司馬懿督張合諸軍，雍、涼劲卒二十萬，潛軍密進，窥向劍閣。蜀相諸葛亮時在祁山，旌旗利器，守在险要。會兵交換，在者八萬。時魏軍始陣，代兵適交，參佐鹹以賊眾強盛，非力不製，宜權停下兵一月，以併聲势。亮曰：「吾統武行師，以大信為本，得利失信，古人所惜；去者束裝以待期，妻子鵠立而計日，雖臨征難，義所不废。」皆催令去。於是，去者皆悅，願留一戰；征者奋勇，思致死命。相謂曰：「諸葛公之恩，死猶未報也。」臨戰之日，莫不拔劍爭先，以一當十，殺張合，却司馬懿，一戰大克，信之由也。","sortOrder":31},
  {"id":"s_work_bckl_1_32","chapterId":"ch_work_bckl_1","text":"〈教戰〉第十","sortOrder":32},
  {"id":"s_work_bckl_1_33","chapterId":"ch_work_bckl_1","text":"凡欲興師，必先教戰。三軍之士，素習離、合、聚、散之法，備谙坐、作、進、退之令，使之遇敵，视旌麾以應变，聽金鼓而進退。如此，則戰無不勝。法曰：「以不教民戰，是謂弃之。」","sortOrder":33},
  {"id":"s_work_bckl_1_34","chapterId":"ch_work_bckl_1","text":"戰國時，魏將吳起曰：「夫人常死其所不能，败其所不便。故用兵之法，教戒為先。一人學戰，教成十人；十人學戰，教成百人；百人學戰，教成千人；千人學戰，教成萬人；萬人學戰，教成三軍。以近待遠，以佚待勞，以飽待飢。圓而方之，坐而起之，行而止之，左而右之，前而後之，分而合之，結而解之。每变皆習，乃授其兵。神而明之，是謂將事。」","sortOrder":34},
  {"id":"s_work_bckl_1_35","chapterId":"ch_work_bckl_1","text":"〔《百戰奇略》卷一終〕","sortOrder":35},
  {"id":"s_work_bckl_2_1","chapterId":"ch_work_bckl_2","text":"卷之二","sortOrder":1},
  {"id":"s_work_bckl_2_2","chapterId":"ch_work_bckl_2","text":"〈眾戰〉第十一","sortOrder":2},
  {"id":"s_work_bckl_2_3","chapterId":"ch_work_bckl_2","text":"凡戰，若我眾敵寡，不可戰於险阻之間，須要平易宽廣之地。聞鼓則進，聞金則止，無有不勝。法曰：「用眾進止。」","sortOrder":3},
  {"id":"s_work_bckl_2_4","chapterId":"ch_work_bckl_2","text":"東晉太元時，秦苻堅進屯寿陽，列陣淝水，與晉將謝玄相拒。玄使謂苻堅曰：「君遠涉吾境，而臨水為陣，是不欲速戰。請君稍却，令將士得周旋，仆與諸君缓辔而觀之，不亦善乎！」堅眾皆曰：「宜阻淝水，莫令得上。我眾彼寡，势必萬全。」堅曰：「但却軍，令得過，而我以鐵騎數十萬，向水逼而殺之。」融亦以為然。遂麾兵使却，眾因亂而不能止。於是，玄與謝琰、桓伊等，以精銳八千渡淝水，右軍拒張耗，小退。玄、琰仍進兵，大戰淝水南，堅眾大潰。","sortOrder":4},
  {"id":"s_work_bckl_2_5","chapterId":"ch_work_bckl_2","text":"〈寡戰〉第十二","sortOrder":5},
  {"id":"s_work_bckl_2_6","chapterId":"ch_work_bckl_2","text":"凡戰，若以寡敵眾，必以日暮，或伏於深草，或邀於隘路，戰則必勝。法曰：「用少者務隘。」","sortOrder":6},
  {"id":"s_work_bckl_2_7","chapterId":"ch_work_bckl_2","text":"《北史》：西魏大統三年，東魏將高歡渡河，逼華州，刺史王霸嚴守。乃涉洛，軍於許原西。西魏遣將宇文泰拒之。泰至渭南，集諸州兵來會。諸將以眾寡不敵，請且待歡更西以觀之。泰曰：「歡若至鹹陽，人情轉搔扰。今其新至，便可击之。」即遣人造浮桥於渭南，軍士赉三日糧，輕騎渡渭，辎重自渭南夹渭而西。十月壬辰，至沙苑，距齊軍六十餘里。高歡率兵來會。候騎告齊兵至，泰召諸將議。李弼曰：「彼眾我寡，不可爭也。宜至此東十里，有渭曲，可據以待之。」遂進至渭曲，背水東西為陣，李弼為右拒，趙貴為左拒。令將士皆偃戈於葭芦之中，聞鼓聲而起。日晡，齊軍至，望見軍少，爭進，卒亂而不成列。兵將交，泰鳴鼓，士卒皆起。於謹等以大軍與之合戰，李弼等率鐵騎橫击之，絕其軍為二，遂犬破之。","sortOrder":7},
  {"id":"s_work_bckl_2_8","chapterId":"ch_work_bckl_2","text":"〈愛戰〉第十三","sortOrder":8},
  {"id":"s_work_bckl_2_9","chapterId":"ch_work_bckl_2","text":"凡與敵戰，士卒寧進死，而不肯退生者，皆將恩惠使然也。三軍知在上之人愛我如子之至，則我之愛上也如父之極。故陷危亡之地，而無不願死以報上之德。法曰：「视卒如愛子，故可與之俱死。」","sortOrder":9},
  {"id":"s_work_bckl_2_10","chapterId":"ch_work_bckl_2","text":"戰國，魏將吳起為西河守，與士卒最下者同衣食。坐不設席，行不乘騎，親裹贏糧，與士卒分勞苦。卒有病疽者，起為吮之。卒母聞而哭之。或曰：「子，卒也，而將軍自吮其疽，何哭也？」母曰：「非然也。往年吳公吮其父，其父戰不旋踵，遂死於敵。吳公今又吮其子，妾不知其死所矣。是以哭之。」文侯以吳起用兵廉平，得士卒心，使守西河，與諸侯大戰七十六，全勝六十四。","sortOrder":10},
  {"id":"s_work_bckl_2_11","chapterId":"ch_work_bckl_2","text":"〈威戰〉第十四","sortOrder":11},
  {"id":"s_work_bckl_2_12","chapterId":"ch_work_bckl_2","text":"凡與敵戰，士卒前進而不敢退後，是畏我而不畏敵也；若敢退而不敢進者，是畏敵而不畏我也。將使士卒赴湯蹈火而不违者，是威嚴使然也。法曰：「威克厥愛，允濟。」","sortOrder":12},
  {"id":"s_work_bckl_2_13","chapterId":"ch_work_bckl_2","text":"春秋，齊景公時，晉伐阿、鄄，而燕侵河上，齊師败績。〔景公患之，〕晏婴乃荐田穰苴，曰：「穰苴雖田氏庶孽，然其人文能附眾、武能威敵，願君试之。」景公乃召穰苴，與語兵事，大悅之，以為將軍，將兵捍燕、晉之師。穰苴曰：「臣素卑賤，君擢之闾伍之中，加之大夫之上，士卒未附，百姓不親，人微權輕，願得君之寵臣、國之所尊，以監軍，乃可。」於是景公許之，使莊贾往。穰苴既辭，與莊贾約：「旦日日中會於軍門。」穰苴先馳至軍中，立表下漏待贾。贾素驕貴，以為將己之軍而己為監，不甚急，親戚左右送之，留飲，日中而贾不至。穰苴則仆表决漏，入，行軍勒兵，申明約束。既定，夕時，贾乃至。穰苴曰：「何為後期？」贾對曰：「不佞，大夫親戚送之，故留。」穰苴曰：「將受命之日則忘其家，臨陣約束則忘其親，援枹鼓之急則忘其身。今敵國深侵，邦內骚動，士卒暴露於境，君寢不安席，食不甘味，百姓之命皆懸於君，何謂相送乎？」召軍正問曰：「軍法，期而後至者雲何？」對曰：「當斬。」贾懼，使人馳報景公，請救。既往，未及返，於是遂斬莊贾以徇三軍。三軍皆震栗。久之，景公遣使持節赦贾，使馳入軍中，穰苴曰：「將在軍，君命有所不受。」問軍正曰：「軍中不馳，今使者馳雲何？」對曰：「當斬。」使者大懼。穰苴曰：「君之使不可殺之。」乃殺其仆、車之左駙、馬之左驂，以徇三軍。遣使者還報，然後行。士卒次舍、井竈、飲食、問疾、医藥，身自拊循之。悉取將軍之資糧，以享士卒，身與士卒平分糧食。最比其羸弱者，三日而後勒兵。病者皆求行，爭奋出為之赴戰。晉師聞之，為罢去；燕師聞之，渡河而解。於是，穰苴乃率眾追击之，遂取所亡邦內故境，率兵而歸。","sortOrder":13},
  {"id":"s_work_bckl_2_14","chapterId":"ch_work_bckl_2","text":"〈賞戰〉第十五","sortOrder":14},
  {"id":"s_work_bckl_2_15","chapterId":"ch_work_bckl_2","text":"凡高城深池，矢石繁下，士卒爭先登；白刃始合，士卒爭先赴者，必誘之以重賞，則敵無不克焉。法曰：「重賞之下，必有勇夫。」","sortOrder":15},
  {"id":"s_work_bckl_2_16","chapterId":"ch_work_bckl_2","text":"漢末，大將曹操每攻城破邑，得靡麗之物，則悉以賞有功者。若勋勞宜賞，不吝千金；無功妄施，分毫不與。故能每戰必勝。","sortOrder":16},
  {"id":"s_work_bckl_2_17","chapterId":"ch_work_bckl_2","text":"〈罰戰〉第十六","sortOrder":17},
  {"id":"s_work_bckl_2_18","chapterId":"ch_work_bckl_2","text":"凡戰，使士卒敢進而不敢退，退一寸者，必懲之以重刑，故可以取勝也。法曰：「罰不遷列。」","sortOrder":18},
  {"id":"s_work_bckl_2_19","chapterId":"ch_work_bckl_2","text":"隋，大將楊素御戎嚴整，有犯軍令者，立斬之，無所宽貸。每將對敵，辄求人過失而斬之，多者百餘人，少者不下十數人。流血盈前，言笑自若。及其對陣，先令三百人赴敵，陷陣則已，如不能陷陣而還者，無問多少，悉斬之。又令二三百人复進，還如向者。將士股栗，有必死之心，由是戰無不勝。","sortOrder":19},
  {"id":"s_work_bckl_2_20","chapterId":"ch_work_bckl_2","text":"〈主戰〉第十七","sortOrder":20},
  {"id":"s_work_bckl_2_21","chapterId":"ch_work_bckl_2","text":"凡戰，若彼為客、我為主，不可輕戰。為吾兵安，士卒顧家，當集人聚穀，保城備险，絕其糧道。彼挑戰不得，轉输不至，俟其困敝而击之，則無不勝矣。法曰：「自戰其地為散地。」","sortOrder":21},
  {"id":"s_work_bckl_2_22","chapterId":"ch_work_bckl_2","text":"《晉書》：後魏武帝，親征後燕慕容德於鄴地，前軍大败績。德又欲攻之，別駕韓[言卓]進曰：「古人先决勝廟堂，然後攻戰。今魏不可击者四，燕不宜動者三。」德曰：「何故？」[言卓]曰：「魏軍遠入，利在野戰，一不可击也。深入近畿，致其死地，二不可击也。前鋒既败，後陣必固，三不可击也。彼眾我寡，四不可击也。官軍自戰其地，一不宜動。動而不勝，眾心難固，二不宜動。城隍未修，敵來未備，三不宜動。此皆兵家所忌，不如深溝高壘，以佚待勞。彼千里饋糧，野無所掠，久則三軍靡費，攻則士卒多毙，師老衅生，起而圖之，可以捷也。」德曰：「別駕之言，真良、平策也。」","sortOrder":22},
  {"id":"s_work_bckl_2_23","chapterId":"ch_work_bckl_2","text":"〈客戰〉第十八","sortOrder":23},
  {"id":"s_work_bckl_2_24","chapterId":"ch_work_bckl_2","text":"凡戰，若彼為主、我為客，唯務深入。深入，則為主者不能勝也。謂客在重地，主在散地故耳。法曰：「深入則专。」","sortOrder":24},
  {"id":"s_work_bckl_2_25","chapterId":"ch_work_bckl_2","text":"漢，韓信、張耳以兵數萬，欲東下井陉击趙。趙王及成安君陳餘聚兵井陉口，眾號二十萬。廣武君李左車說成安君曰：「聞韓信涉西河，擄魏豹，擒夏悅，新喋血閼與。今乃辅以張耳，議欲以下趙，此乘勝而去國遠斗，其風聲所及，足以奪人，其鋒何可擋也。臣聞：千里饋糧，士有飢色，樵蘇而爨，師不宿飽。今井陉之道，車不得方軌，騎不得成列，〔行數百里〕，其势糧食必在其後。願足下假臣奇兵三萬人，從間道絕其辎重，足下深溝高壘勿與戰。彼前不能斗，退不能還，〔吾奇兵絕其後，使〕野無所掠，不至十日，兩將之頭可懸麾下。願君留意。否則，必為所擒。」成安君自以為義兵，〔不用诈謀奇計〕，不聽其策，果被殺。","sortOrder":25},
  {"id":"s_work_bckl_2_26","chapterId":"ch_work_bckl_2","text":"〈強戰〉第十九","sortOrder":26},
  {"id":"s_work_bckl_2_27","chapterId":"ch_work_bckl_2","text":"凡與敵戰，若我眾強，可伪示怯弱以誘之，敵必輕來與我戰，吾以銳卒击之，其軍必败。法曰：「能而示之不能。」","sortOrder":27},
  {"id":"s_work_bckl_2_28","chapterId":"ch_work_bckl_2","text":"戰國，趙將李牧常居雁門，備匈奴。以便宜置吏，市租皆输入幕府，為士卒費。日击數牛享士，習騎射，謹烽火，多間諜，厚遇將士，約曰：「匈奴入盜，急入收保，有敢捕虜者，斬。」匈奴每入盜，辄入收保，不與戰。如是數歲，無所亡失。然匈奴以李牧為怯，雖趙邊兵亦以為吾將怯。趙王讓李牧，李牧如故。趙王召之，使人代牧將。歲餘，匈奴來，每出戰，數不利，失亡多，邊不得田畜。於是复請牧。牧稱疾，杜門不出。趙王乃复強起使將兵。牧曰：「若用臣，臣如前，乃敢奉命。」王許之。李牧遂往，至，如故約。匈奴來無所得，終以為怯。邊士日得賞賜，不用，皆願一戰。於是乃具選車得一千三百乘","sortOrder":28},
  {"id":"s_work_bckl_2_29","chapterId":"ch_work_bckl_2","text":"，選騎得一萬三千匹、百金之士五萬人、控絃者十萬人，悉勒兵習戰，大縱畜牧，人民滿野。匈奴來，佯败不勝，以數千人委之。单於聞之，大率眾來入。李牧多為奇陣，張左右翼以击之，大破之，殺匈奴十萬餘騎，单於奔走。其後十餘歲，匈奴不敢犯趙邊。","sortOrder":29},
  {"id":"s_work_bckl_2_30","chapterId":"ch_work_bckl_2","text":"〈弱戰〉第二十","sortOrder":30},
  {"id":"s_work_bckl_2_31","chapterId":"ch_work_bckl_2","text":"凡與敵戰，若敵眾我寡，敵強我弱，須多設旌旗，倍增火竈，示強於敵，使彼莫能测我眾寡、強弱之形，則敵必不輕與我戰。我可速去，則全軍遠害。法曰：「強弱，形也。」","sortOrder":31},
  {"id":"s_work_bckl_2_32","chapterId":"ch_work_bckl_2","text":"後漢，羌胡反，寇武都。邓太後以虞詡有將帥之略，遷武都太守。羌乃率眾數千，遮詡於陳仓、崤穀。詡即停軍不進，而宣言上書請兵，須到當發。羌聞之，乃分抄傍縣。詡因其兵散，日夜倍道兼行，日行百餘里。令吏士各作兩竈，日增倍之，羌不敢逼。或問曰：「孫臏减竈而君增之。兵法：日行不過三十里，而今日且行百里，何也？」詡曰：「虜眾多，吾今兵少。吾之增竈，使敵必謂郡兵來迎。眾多行速，必憚追我。孫臏見弱，吾今示強，势有不同故也。」","sortOrder":32},
  {"id":"s_work_bckl_2_33","chapterId":"ch_work_bckl_2","text":"〔《百戰奇略》卷二終〕","sortOrder":33},
  {"id":"s_work_bckl_3_1","chapterId":"ch_work_bckl_3","text":"卷之三","sortOrder":1},
  {"id":"s_work_bckl_3_2","chapterId":"ch_work_bckl_3","text":"〈驕戰〉第二十一","sortOrder":2},
  {"id":"s_work_bckl_3_3","chapterId":"ch_work_bckl_3","text":"凡敵人強大，未能必取，須當卑辭厚禮，以驕其志。候其有隙可乘，一舉可破。法曰：「卑而驕之。」","sortOrder":3},
  {"id":"s_work_bckl_3_4","chapterId":"ch_work_bckl_3","text":"蜀將關羽北伐，擒魏將於禁，围曹仁於樊。吳將呂蒙在陆口稱疾，詣建業，陆遜往見之，謂曰：「關羽接境，如何遠下，後不堪忧也！」蒙曰：「誠如來言，然我病篤。」遜曰：「羽矜其功，驕氣凌鑠於人。〔始有大功，意驕志逸，但務北進，無嫌於我。〕又相聞病，必益無備。今出其不意，自可擒製。若見至尊，宜好為計。」蒙曰：「羽素勇猛，既難與敵，且已據荆州，恩信大布，兼始有功，胆氣益堅，未易圖也。」蒙至都，權問：「卿病，誰可代者？」蒙對曰：「陆遜慮思深長，才堪負重，觀其規慮，終可大任。而未有遠名，非羽所忌，無复是過。若用之，當令外自韜隱，內察形便，然後可克。」權乃召遜，拜偏將軍右都督代蒙。遜至陆口，書與羽曰：「前承觀衅而動，以律行師，小舉大克，亦何巍巍！敵國败績，利在同盟，聞慶撫節，相遂席卷，共奖王綱。某不敏，受任來西，延慕光尘，思禀良規。」又曰：「於禁等見獲，遐邇欣叹，以為將軍之勋足以長世，雖畴昔晉文城濮之師，淮陰拔趙之略，蔑以尚之。聞徐晃等步騎駐旌，窥望麾葆。操猾虜也，忿不思難，恐潛增眾，以逞其心。雖雲師老，猶有驍悍。且戰捷之後，常苦輕敵，古術軍勝弥警，願將軍廣為方針，以全獨克。某書生疏遲，忝所不堪，嘉鄰威德，樂自傾盡，雖未合策，猶可懷也。〔傥明註仰，有以察之。〕」羽覽書有謙下之意，遂大安，無复所嫌。遜具啟状，陳其可擒之要。權乃潛軍而上，使遜與呂蒙為前部，至，即克公安、南郡。","sortOrder":4},
  {"id":"s_work_bckl_3_5","chapterId":"ch_work_bckl_3","text":"〈交戰〉第二十二","sortOrder":5},
  {"id":"s_work_bckl_3_6","chapterId":"ch_work_bckl_3","text":"凡與敵戰，傍與鄰國，當卑辭厚賂以結之，引為己援。若我攻敵人之前，彼犄其後，則敵人必败。法曰：「衢地則合交。」","sortOrder":6},
  {"id":"s_work_bckl_3_7","chapterId":"ch_work_bckl_3","text":"三國，蜀將關羽，围魏曹仁於樊，魏遣左將軍於禁等救之，會漢水暴起，羽以舟兵虜禁等步騎三萬，送江陵。是時，漢帝都許昌，魏武以為近賊，欲徙河北，以避其鋒。司馬懿諫曰：「禁等為水所没，非戰守之所失，於國家大計未有所損，而便遷都，既示敵以弱，又淮、沔之人俱不安矣。孫權、劉備，外親而內疏，羽今得意，權必不願也。可諭權，令犄其後，則樊围自解。」魏武從之，遣使結權。權遂遣呂蒙西袭公安、南郡，拔之，羽果弃樊而去。","sortOrder":7},
  {"id":"s_work_bckl_3_8","chapterId":"ch_work_bckl_3","text":"〈形戰〉第二十三","sortOrder":8},
  {"id":"s_work_bckl_3_9","chapterId":"ch_work_bckl_3","text":"凡與敵戰，若彼眾多，則虛設形以分其势，彼不敢不分兵以備我。敵势既分，其兵必寡；我专為一，其卒自眾。以眾击寡，無有不勝。法曰：「形人而我無形。」","sortOrder":9},
  {"id":"s_work_bckl_3_10","chapterId":"ch_work_bckl_3","text":"漢末，建安五年，曹操與袁紹相拒於官渡。紹遣郭圖、淳於琼、顏良，攻操將東郡太守劉延於白馬，紹率兵至黎陽，將渡河。夏四月，曹操北救延。荀攸說操曰：「今兵少不可敵，若分其势乃可。公到延津，若將渡河向其後，紹必西應之。然後輕兵袭白馬，掩其不備，顏良可擒也。」操從之。紹聞操兵將渡，即分兵西應之。操乃率軍兼行趨白馬，未至十餘里，良大驚，來迎戰。操使張遼、關羽前登，击破之，斬良，遂解白馬之围。","sortOrder":10},
  {"id":"s_work_bckl_3_11","chapterId":"ch_work_bckl_3","text":"〈势戰〉第二十四","sortOrder":11},
  {"id":"s_work_bckl_3_12","chapterId":"ch_work_bckl_3","text":"凡戰，所謂势者，乘势也。因敵有破滅之势，則我從而迫之，其軍必潰。法曰：「因势而破之。」","sortOrder":12},
  {"id":"s_work_bckl_3_13","chapterId":"ch_work_bckl_3","text":"晉武帝密有滅吳之計，而朝議多违，惟羊祜、杜預、張華與帝意合。祜病，舉預自代。及祜卒，拜預镇南大將軍，都督荆州諸軍事。既至镇，繕甲兵，耀威武，遂揀精銳，袭破吳西陵都督張政，乃啟請伐吳之期。帝報待明年方欲大舉。預上表曰：「凡事當以利害相期，今此舉十有八九之利，而其害一二，止於無功耳。朝臣言破败之形，亦不可得，直是計不出己，功不在身，各恥其前言之失，故违之耳。昔漢宣帝議趙充國所上事，效之後，责諸議者，皆叩頭而謝，以塞異端也。自秋以來，讨賊之形頗露。若今中止，孫皓怖而生計，或徙都武昌，更添修江南諸城，遠其居人，城不可攻，野無所掠，積大船於夏口，","sortOrder":13},
  {"id":"s_work_bckl_3_14","chapterId":"ch_work_bckl_3","text":"則明年之計或無所及矣。」時帝與張華围棋，而預表適至。華推枰斂手曰：「陛下聖明神武，國富兵強。吳王淫虐，誅殺賢能，當今讨之，可不勞而定。」帝乃許之。預陳兵江陵，遣周旨、伍巢等率奇兵泛舟夜渡，以袭樂乡，多張旗幟，起火巴山，出於要害之地，以奪賊心，遂獲吳都督孫歆。既平上流，於是湘江以南，至於交、廣，吳之州郡，望風歸附。預仗節宣詔而綏撫之。時諸將會議，或曰：「百年之寇，未易盡克。今大暑，水潦方降，疾疫將起，宜伺來冬，更為大舉。」預曰：「昔樂毅借濟西一戰，以併強齊。今兵威已振，譬如破竹，數節之後，皆迎刃而解，無复著手處也。」遂指授群帥，径造秣陵，所過城邑，莫不束手，遂平孫皓。","sortOrder":14},
  {"id":"s_work_bckl_3_15","chapterId":"ch_work_bckl_3","text":"〈晝戰〉第二十五","sortOrder":15},
  {"id":"s_work_bckl_3_16","chapterId":"ch_work_bckl_3","text":"凡與敵晝戰，須多設旌旗，以為疑兵，使敵莫能测其眾寡，則勝。法曰：「晝戰多旌旗。」","sortOrder":16},
  {"id":"s_work_bckl_3_17","chapterId":"ch_work_bckl_3","text":"春秋，晉侯伐齊，齊侯登山以望晉師。晉人使斥山泽之险，雖所不至，必旆而疏陳之。使乘車者左實右伪，以旆先，舆曳柴而從之。齊侯見之，畏其眾也，遂逃歸。","sortOrder":17},
  {"id":"s_work_bckl_3_18","chapterId":"ch_work_bckl_3","text":"〈夜戰〉第二十六","sortOrder":18},
  {"id":"s_work_bckl_3_19","chapterId":"ch_work_bckl_3","text":"凡與敵夜戰，須多用火鼓，所以变亂敵之耳目，使其不知所以備我之計，則勝。法曰：「夜戰多火鼓。」","sortOrder":19},
  {"id":"s_work_bckl_3_20","chapterId":"ch_work_bckl_3","text":"春秋，越伐吳。吳人御之笠泽，夹水而陣。越為左右二軍，乘夜，或左或右，鼓噪而進；吳分兵御之。越子率中軍潛涉，當吳中軍而鼓之，吳師大亂，遂败之。","sortOrder":20},
  {"id":"s_work_bckl_3_21","chapterId":"ch_work_bckl_3","text":"〈備戰〉第二十七","sortOrder":21},
  {"id":"s_work_bckl_3_22","chapterId":"ch_work_bckl_3","text":"凡出師征讨，行則備其邀截，止則御其掩袭，營則防其偷盜，風則恐其火攻。若此設備，有勝而無败。法曰：「有備不败。」","sortOrder":22},
  {"id":"s_work_bckl_3_23","chapterId":"ch_work_bckl_3","text":"三國，魏大將吳璘征南，兵到精湖，魏將滿寵帥諸將在前，與敵夹水相對。寵謂諸將曰：「今夕風甚猛，敵必來燒營，宜為之備。」諸將皆警。夜半，敵果遣十部〔伏〕來燒營，寵掩击，大破之。","sortOrder":23},
  {"id":"s_work_bckl_3_24","chapterId":"ch_work_bckl_3","text":"〈糧戰〉第二十八","sortOrder":24},
  {"id":"s_work_bckl_3_25","chapterId":"ch_work_bckl_3","text":"凡與敵對壘，勝負未决，有糧則勝。若我之糧道，必須嚴加守護，恐為敵人所抄。若敵人之餉道，可分銳兵以絕之。敵既無糧，其兵必走，击之則勝。法曰：「軍無糧食則亡。」","sortOrder":25},
  {"id":"s_work_bckl_3_26","chapterId":"ch_work_bckl_3","text":"漢末，曹操與袁紹相持於官渡。紹遣軍運糧，使淳於琼等五人將兵萬餘人送之，宿紹營北四十里。紹謀臣許攸貪财，紹不能足，奔歸操，因說操曰：「今袁紹有辎重萬餘乘，而乏嚴備，今以輕兵袭之，燔其積聚，不過三日，袁氏自败矣。」左右〔疑之〕，荀攸、贾詡勸操。〔操〕乃留曹洪守，自將步騎五千人，皆用袁軍旗幟，衔枚縛馬口，夜從間道出，人負束薪，所歷道有問者，語之曰：「袁公恐操抄掠後軍，遣軍益備。」聞者信以為然，皆自若。既至，围屯，即放火，營中驚亂，大败之。紹弃甲而遁。","sortOrder":26},
  {"id":"s_work_bckl_3_27","chapterId":"ch_work_bckl_3","text":"〈导戰〉第二十九","sortOrder":27},
  {"id":"s_work_bckl_3_28","chapterId":"ch_work_bckl_3","text":"凡與敵戰，山川之夷险，道路之迂直，必用乡人引而导之，乃知其利，而戰則勝。法曰：「不用乡导者，不能得地利。」","sortOrder":28},
  {"id":"s_work_bckl_3_29","chapterId":"ch_work_bckl_3","text":"漢武帝時，匈奴比歲入寇，所殺掠甚眾。元朔五年春，今衛青將三萬騎出塞，匈奴右賢王以為漢兵不能至此，遂醉臥帳中。漢兵夜至，围，右賢王遂大驚，獨與其愛妾一人、騎兵數百，潰围夜逃北去。漢遣輕騎校尉郭成等追四百里，弗及，得虜裨王十餘人，男女萬五千餘口，畜馬數百萬。於是，青率兵而還。至塞，天子使使者持大將軍印，即軍中拜青為大將軍，諸將皆以兵屬，立號而歸。皆用校尉。","sortOrder":29},
  {"id":"s_work_bckl_3_30","chapterId":"ch_work_bckl_3","text":"張騫以嘗使大夏，留匈奴久，导軍，善知水草處，大軍得以無飢渴之患焉。","sortOrder":30},
  {"id":"s_work_bckl_3_31","chapterId":"ch_work_bckl_3","text":"〈知戰〉第三十","sortOrder":31},
  {"id":"s_work_bckl_3_32","chapterId":"ch_work_bckl_3","text":"凡興兵伐敵，所戰之地，必預知之。師至之日，能使敵人如期而來，與戰則勝。知戰地，知戰日，則所備者专，所守者固。法曰：「知戰之地，知戰之日，則可千里而會戰。」","sortOrder":32},
  {"id":"s_work_bckl_3_33","chapterId":"ch_work_bckl_3","text":"戰國，魏與趙攻韓，韓告急於齊。齊用田忌將而往，直走大梁。魏將庞涓聞之，去韓而歸。孫臏謂田忌曰：「彼三晉之兵，素悍勇而輕齊，齊號為怯。善戰者因其势而利导之。兵法：百里而趨利者，蹶上將；五十里而趨利者，軍半至。使齊軍入魏地為十萬竈，明日為五萬竈，又明日為三萬竈。」涓追三日，大喜，曰：「我固知齊軍怯，入吾地三日，士卒亡者過半矣。」乃弃其步軍，與精銳親兵倍道兼行逐之。孫臏度其行，暮當至馬陵。〔馬陵〕道狹，而旁多阻隘，可伏兵，乃斫大木白而書之曰：「庞涓死此树下」。於是令齊軍善射者萬弩夹道而伏。期曰：「暮見舉火即萬弩俱發。」涓果夜至，立木下見白書，乃鑽火燭之。讀其書未畢，齊軍萬弩俱發，魏軍大亂。涓自知智窮兵败，乃自刎。","sortOrder":33},
  {"id":"s_work_bckl_3_34","chapterId":"ch_work_bckl_3","text":"〔《百戰奇略》卷三終〕","sortOrder":34},
  {"id":"s_work_bckl_4_1","chapterId":"ch_work_bckl_4","text":"卷之四","sortOrder":1},
  {"id":"s_work_bckl_4_2","chapterId":"ch_work_bckl_4","text":"〈斥戰〉第三十一","sortOrder":2},
  {"id":"s_work_bckl_4_3","chapterId":"ch_work_bckl_4","text":"凡行兵之法，斥候為先。平易用騎，险阻用步。每五人為一甲，人持一白旗，遠則軍行前後左右，接續候望。若見賊兵，以次轉近，告白主將，令眾預為之備。法曰：「以虞待不虞者勝。」","sortOrder":3},
  {"id":"s_work_bckl_4_4","chapterId":"ch_work_bckl_4","text":"漢宣帝時，先零諸羌叛，犯邊塞，攻城邑，殺長吏。時後將軍趙充國，年七十餘，上老之，使〔御史大夫丙吉〕問：誰可將者？〔充國對曰：「亡逾於老臣者。」上遣問焉，曰：「將軍度羌虜何如，當用幾人？」〕充國曰：「百聞不如一見。兵難預度，臣願馳至金城，圖上方略。然羌戎小夷，逆天背叛，滅亡不久，願陛下屬之老臣，勿以為忧。」上笑曰：「诺。」充國至金城，須兵滿萬騎，欲渡河，恐為虜所遮。即夜遣三校衔枚先渡，渡辄營陣。會明，遂以次盡渡。羌數十百騎來，出入軍傍。充國曰：「吾士馬新至困倦，不可馳逐。此皆驍騎難製，又恐為其誘兵也。击羌以殄滅為期，小利不足貪。」令軍中勿击。遣騎候望四望峡中，無羌。夜半兵至落都，召諸校、司馬，謂曰：「吾知羌戎不能為矣。使彼發數千人守杜四望峡中，兵眾豈得入來！」充國常以遠斥候為務，行必為戰備，止必堅營壁，尤能持重，愛士卒，先計而後戰。遂平先零。","sortOrder":4},
  {"id":"s_work_bckl_4_5","chapterId":"ch_work_bckl_4","text":"〈泽戰〉第三十二","sortOrder":5},
  {"id":"s_work_bckl_4_6","chapterId":"ch_work_bckl_4","text":"凡出軍行師，或遇沮泽、圮毀之地，宜倍道兼行速過，不可稽留也。若不得已，與不能出其地，道遠日暮，宿師於其中，必就地形之環龟，其中高，四下為圓營，四面當敵。一則防水潦之厄，一則備四围之寇。法曰：「歷沛歷圮，堅舍環龟。」","sortOrder":6},
  {"id":"s_work_bckl_4_7","chapterId":"ch_work_bckl_4","text":"唐，調露元年，突厥阿史德溫傅反。詔禮部尚書、檢校右衛大將軍裴行俭為定襄道行軍大總管讨之。軍次单於界北，暮，已立營，堑壕既周，行俭更命徙營高岡。吏曰：「吏士安堵，不可扰。」不聽，徙之。比夜，風雨雷霆暴至，前設營所，水深丈餘，眾莫不駭叹，因問何以知其有風雨也，行俭笑曰：「自今但依我節製，勿問我所由知也。」","sortOrder":7},
  {"id":"s_work_bckl_4_8","chapterId":"ch_work_bckl_4","text":"〈爭戰〉第三十三","sortOrder":8},
  {"id":"s_work_bckl_4_9","chapterId":"ch_work_bckl_4","text":"凡與敵戰，若有形势便利之處，宜爭先據之，以戰則勝。若敵人先至，我不可攻，候其有变則击之，乃利。法曰：「爭地勿攻。」","sortOrder":9},
  {"id":"s_work_bckl_4_10","chapterId":"ch_work_bckl_4","text":"三國，魏青龍二年，蜀將諸葛亮出斜穀。是時，魏將司馬懿屯渭南，郭淮策亮必爭北原，宜先據之，議者多謂不然。淮曰：「若亮跨渭登原，連兵北山，隔絕隴道，搖荡民心，此非國之利也。」懿善之，淮遂屯北原。堑壘未成，蜀兵大至，淮遂逆击之。後數日，亮盛兵西行，淮將皆以為欲攻西围，淮獨以亮見形於西，欲使兵眾應之，必攻東耳。其夜，果攻陽遂，有備不败。","sortOrder":10},
  {"id":"s_work_bckl_4_11","chapterId":"ch_work_bckl_4","text":"〈地戰〉第三十四","sortOrder":11},
  {"id":"s_work_bckl_4_12","chapterId":"ch_work_bckl_4","text":"凡與敵戰，三軍必要得其地利，則可以寡敵眾，以弱勝強。所謂知敵之可击，知吾卒之可以击，而不知地利，勝之半也。此言既知彼又知己，但不得地利之助，則亦不全勝。法曰：「天時不如地利。」","sortOrder":12},
  {"id":"s_work_bckl_4_13","chapterId":"ch_work_bckl_4","text":"宋武帝讨南燕。慕容超召群臣議拒晉師。公孫五樓曰：「晉師劲果，所利在速戰，初鋒勇銳，不可击也。宜據大峴，使不得入。曠日延時，沮其銳氣。可徐揀精兵二千騎，循海而南，絕其糧道；別遣段暉率諸州之軍，緣山東下。腹背击之，此上策也。各命守宰依险自固，较其資储之外，餘悉焚荡，芟除粟苗，使敵來無所資，堅壁清野，以待其衅，中策也。縱賊入峴，出城迎戰，下策也。」超曰：「京都富盛，戶口眾多，非可以一時入守。青苗布野，非可以猝芟。設使芟苗守城，以全性命，朕所不能。〔今〕據五州之強，帶山河之固，戰車萬乘，鐵馬萬群，縱令過峴，至於平地，徐以精騎蹂之，必成擒也。」慕容镇曰：「若如聖旨，必須平原十里而軍，軍壘成，用馬為便宜，出峴逆戰而不勝，猶可退守。不宜縱敵人峴，自貽窘迫。昔成安君不守井陉之险，終屈於韓信；諸葛瞻不守劍閣之险，卒擒於邓艾。臣以天時不如地利也，阻守大峴，策之上也。」超又不從。而攝莒、梁父二戍，修城隍，揀士馬，蓄銳以待之。其夏，晉師已次〔東莞〕，超遣其左軍段暉等步騎五萬，進據臨朐。俄而，晉師渡峴，慕容超懼，率兵四萬就段暉等於臨朐，戰败，超奔廣固，數日而拔，燕地悉平。","sortOrder":13},
  {"id":"s_work_bckl_4_14","chapterId":"ch_work_bckl_4","text":"〈山戰〉第三十五","sortOrder":14},
  {"id":"s_work_bckl_4_15","chapterId":"ch_work_bckl_4","text":"凡與敵戰，或居山林，或在平陆，須居高阜，恃其形势，順於击刺，便於奔冲，以戰則勝。法曰：「山陵之戰，不仰其高。」","sortOrder":15},
  {"id":"s_work_bckl_4_16","chapterId":"ch_work_bckl_4","text":"戰國，秦伐韓〔，軍於閼與〕。韓求救於趙，王召廉頗而問曰：「可救否？」曰：「道遠路狹，難救。」又召樂乘而問曰：「可救否？」樂乘對如頗言。又召趙奢問，奢曰：「道遠路狹，譬如兩鼠斗於穴中，將勇者勝。」王乃令奢將，救之。兵去趙國都三十里，壘，不進，而令軍中曰：「有以軍事諫者死。」秦軍武安〔西〕。有一人諫，奢立斬之。堅壁，留二十八日不行，复益增壘。秦間來入，趙奢善食而遣之。間以報秦將，秦將大喜，曰：「夫去國三十里而軍不行，乃增壘，非趙地也。」趙奢既遣秦間，乃卷甲而趨之，一晝夜至，〔令善射者去閼與五十里而軍。軍壘成，〕秦聞之，悉甲而至。軍士許歷請入諫，趙奢內之。許歷曰：「秦人不意趙師至此，其來氣盛，將軍必厚集其陣以待之。不然，必败。」奢曰：「請受教。」歷曰：「請受刑。」奢曰：「須後令至邯鄲。」歷复請〔諫〕曰：「先據北山者勝，後至者败。」趙奢曰：「诺。」即發萬人趨之。秦兵後至，爭山不得上，奢縱兵击之，大破秦軍，遂解其围。","sortOrder":16},
  {"id":"s_work_bckl_4_17","chapterId":"ch_work_bckl_4","text":"〈穀戰〉第三十六","sortOrder":17},
  {"id":"s_work_bckl_4_18","chapterId":"ch_work_bckl_4","text":"凡行軍越過山险而陣，必依附山穀，一則利水草，一則附险固，以戰則勝。法曰：「絕山依穀。」","sortOrder":18},
  {"id":"s_work_bckl_4_19","chapterId":"ch_work_bckl_4","text":"後漢將馬援為隴西太守，三絳羌與塞外諸种為寇，殺長吏。援將四千餘人击之，至氐道縣。羌在山上，援軍據便地，奪其水草，不與戰，羌遂窮困。羌師數十萬戶亡出塞外，諸种萬餘人悉降。羌不知依穀之利，而取败焉。","sortOrder":19},
  {"id":"s_work_bckl_4_20","chapterId":"ch_work_bckl_4","text":"〈攻戰〉第三十七","sortOrder":20},
  {"id":"s_work_bckl_4_21","chapterId":"ch_work_bckl_4","text":"凡戰，所謂攻者，知彼者也。知彼有可破之理，則出兵以攻之，無有不勝。法曰：「可勝者，攻也。」","sortOrder":21},
  {"id":"s_work_bckl_4_22","chapterId":"ch_work_bckl_4","text":"三國，魏曹操遣朱光為庐江太守，屯皖，大开稻田，又令間人招誘鄱陽賊帥，使作內應。吳將呂蒙曰：「皖田肥美，若一收熟，彼眾必增，如是數歲，操難製矣，宜早除之。」乃具陳其状。於是孫權親征〔皖〕，一朝夜至。問諸將計策，諸將皆勸作高壘。蒙曰：「治壘必歷日乃成，彼城備已修，外救必至，不可圖也。且乘雨水以入，若淹留數日，必須盡還，還道艱難，蒙竊危之。今觀此城不甚固，以三軍銳氣，四面攻之，不移時可拔，及水未涨而歸，全勝之術也。」吳主權從之。蒙乃荐甘寧為外城都督，率兵攻其前，蒙以精銳繼之。侵晨進攻，蒙手執枹鼓，士卒皆騰踴自升，食時破之。既而張遼至夹石，聞城已拔，乃退。權嘉蒙功，即拜庐江太守。","sortOrder":22},
  {"id":"s_work_bckl_4_23","chapterId":"ch_work_bckl_4","text":"〈守戰〉第三十八","sortOrder":23},
  {"id":"s_work_bckl_4_24","chapterId":"ch_work_bckl_4","text":"凡戰，所謂守者，知己者也。知己未有可勝之理，則我且固守，待敵可破之時，則出兵以攻之，無有不勝。法曰：「知不可勝，則守。」","sortOrder":24},
  {"id":"s_work_bckl_4_25","chapterId":"ch_work_bckl_4","text":"漢景帝時，吳、楚七國反，以周亚夫為太尉，東击吳、楚七國。因自請於上曰：「楚兵剽輕，難與爭鋒，願以梁委之；絕其食道，乃可製也。」上許之。亚夫至，會兵滎陽。吳方攻梁，梁急，請救於亚夫。亚夫率兵東北走昌邑，堅壁而守。梁王使使請亚夫，亚夫守便宜，不往救。梁上書於景帝，帝詔亚夫救梁。亚夫不奉詔，堅壁不出，而使弓高侯等將輕騎，絕吳、楚兵後食道。吳、楚兵乏糧，飢，欲退，數挑戰，終不出。夜，亚夫軍中驚亂，自相攻击至於帳下。亚夫堅臥不起，頃之，自定。吳奔壁東南陬，亚夫使備西北。已而，吳兵果奔西北，不得入。吳、楚兵飢，乃引兵退。亚夫出精兵追击，大破之。吳王濞弃其軍，與壮士數千人亡走，保於江南丹徒。漢兵因乘勝追击，盡獲之，降其郡縣。亚夫下令曰：「有得吳王者，賞千金。」月餘，越人斬首以告。凡相攻守七月，而吳、楚悉平。","sortOrder":25},
  {"id":"s_work_bckl_4_26","chapterId":"ch_work_bckl_4","text":"〈先戰〉第三十九","sortOrder":26},
  {"id":"s_work_bckl_4_27","chapterId":"ch_work_bckl_4","text":"凡與敵戰，若敵人初來，陣势未定，行陣未整，先以兵急击之，則勝。法曰：「先人有奪人之心。」","sortOrder":27},
  {"id":"s_work_bckl_4_28","chapterId":"ch_work_bckl_4","text":"春秋，宋襄公及楚人戰於泓，宋人既成列，楚人未既濟。司馬子魚曰：「彼眾我寡，及其未既濟，請击之。」公弗許。既濟，未成列，子魚复請，公又不許。及成列而戰，宋師败績。","sortOrder":28},
  {"id":"s_work_bckl_4_29","chapterId":"ch_work_bckl_4","text":"〈後戰〉第四十","sortOrder":29},
  {"id":"s_work_bckl_4_30","chapterId":"ch_work_bckl_4","text":"凡戰，若敵人行陣整而且銳，未可與戰，宜堅壁待之；候其陣久氣衰，起而击之，無有不勝。法曰：「後於人以待其衰。」","sortOrder":30},
  {"id":"s_work_bckl_4_31","chapterId":"ch_work_bckl_4","text":"唐，武德中，太宗围王世充於東都，窦建德率眾來救。太宗守武牢以拒之。建德陣汜水東，弥亘數里，諸將皆有懼色。太宗將數騎登高以望之，謂諸將曰：「賊起山東，未見大敵。今渡险而嚣，是軍無政令；逼城而陣者，有輕我之心也。我按兵不動，待彼氣衰，陣久卒飢，必將自退，退而击之，何往不克！」建德列陣，自卯至午時，卒飢倦列坐，又爭飲水。太宗令宇文士及率三百騎，經賊陣之西，馳而南，誡曰：「賊若不動，止，宜退歸；如覺其動，宜率東出。」士及才過，賊眾果動。太宗曰：「可击矣。」士及命騎將建旗列陣，自武牢乘高入南山，循穀而東，以掩賊背。建德遽率其師却，止東原，未及整列，太宗輕騎击之，所向披靡。程咬金等眾騎纏幡而入，直突出賊陣後，齊張旗幟，表里俱備，賊眾大潰，生擒建德。","sortOrder":31},
  {"id":"s_work_bckl_4_32","chapterId":"ch_work_bckl_4","text":"〔《百戰奇略》卷四終〕","sortOrder":32},
  {"id":"s_work_bckl_5_1","chapterId":"ch_work_bckl_5","text":"卷之五","sortOrder":1},
  {"id":"s_work_bckl_5_2","chapterId":"ch_work_bckl_5","text":"〈奇戰〉第四十一","sortOrder":2},
  {"id":"s_work_bckl_5_3","chapterId":"ch_work_bckl_5","text":"凡戰，所謂奇者，攻其無備，出其不意也。交戰之际，驚前掩後，冲東击西，使敵莫知所備，如此則勝。法曰：「敵虛，則我必為奇。」","sortOrder":3},
  {"id":"s_work_bckl_5_4","chapterId":"ch_work_bckl_5","text":"三國，魏景元四年，詔諸軍征蜀，大將軍司馬宣王指授節度，使邓艾與蜀將薑維相缀連於雍州，刺史諸葛緒邀維，令不得歸。艾遣天水太守王頎等直攻維營，隴西太守牵弘邀其前，金城太守楊欣詣甘松。維聞鐘會諸軍已入漢中，退還。欣等躡於強川口，大戰，維败走。聞雍州已塞道，屯桥頭，乃從孔函穀入北道，欲出雍州後。諸葛緒聞之，却還三十里。維入北道三十里，聞緒軍却，〔尋〕還，從桥頭欲過，緒趣截維，较一日不及。維遂東，還守劍閣。鐘會攻維，未能克。艾上言：「今賊摧折，宜遂從陰平由邪径出漢中、德陽亭趣涪，去劍閣西百里，去成都三百里，奇兵冲其腹心。劍閣之守必還，赴涪，則會方軌而進；劍閣之軍不還，則應涪之兵寡矣。《軍志》曰：攻其無備，出其不意。今掩其空虛，破之必矣。」〔冬十月。〕艾自陰平道行無人之地七百餘里，凿山信道，造作桥閣，山高穀深，至為艱難，糧運將匮，頻至危殆。艾以氈自裹，推轉而下；將士皆攀木緣崖，魚貫而進，先登至江油，蜀守將馬邈降。蜀衛將軍諸葛瞻自涪還綿竹，列陣待艾。艾遣其子邓忠出其右、司馬師綦等出其左。忠、綦戰不利，併退還，曰：「賊未可勝。」艾怒曰：「存亡之分，在此一舉，何不可之有？」乃叱忠、綦等，將斬之。忠、綦馳還更戰，大破之，斬瞻，進軍成都。劉禪遣使請降，遂滅蜀。","sortOrder":4},
  {"id":"s_work_bckl_5_5","chapterId":"ch_work_bckl_5","text":"〈正戰〉第四十二","sortOrder":5},
  {"id":"s_work_bckl_5_6","chapterId":"ch_work_bckl_5","text":"凡與敵戰，若道路不能通，糧餉不能進，推計不能誘，利害不能惑，須用正兵。正兵者，揀士卒，利器械，明賞罰，信號令。且戰且前，則勝矣。法曰：「非正兵，安能致遠？」","sortOrder":6},
  {"id":"s_work_bckl_5_7","chapterId":"ch_work_bckl_5","text":"宋檀道濟為高祖北伐前鋒，至洛陽，凡拔城破壘，俘四千餘人。議者謂應戮以為京觀。道濟曰：「伐罪弔民，正在今日。王師以正為律，何必殺人！」皆釋而遣之。於是戎夷感悅，相率歸之者眾。","sortOrder":7},
  {"id":"s_work_bckl_5_8","chapterId":"ch_work_bckl_5","text":"〈虛戰〉第四十三","sortOrder":8},
  {"id":"s_work_bckl_5_9","chapterId":"ch_work_bckl_5","text":"凡與敵戰，若我势虛，當伪示以實形，使敵莫能测其虛實所在，必不敢輕與我戰，則我可以全師保軍。法曰：「敵不得與我戰者，乖其所之也。」","sortOrder":9},
  {"id":"s_work_bckl_5_10","chapterId":"ch_work_bckl_5","text":"三國，蜀將諸葛亮在陽平，魏延諸將併兵東下，亮惟留萬餘守城。魏司馬懿率二十萬眾拒亮，與延軍错道，径前，當亮軍六十里，候還，白懿雲：「亮城中兵少力弱。」亮亦知懿軍垂至，恐與己相逼，欲赴延軍，相去又遠，势不能及。將士失色，莫知其計。亮意氣自若，敕命軍中皆偃旗息鼓，不得妄出；又令大开四門，扫地却洒。懿嘗謂亮持重，而复見以弱势，疑其有伏兵。於是，率眾退北山。明日食時，亮與參佐拊手大笑曰：「司馬必謂吾示怯，將有強伏，循山走矣。」候還白，如亮言。懿後知之，深以為恨。","sortOrder":10},
  {"id":"s_work_bckl_5_11","chapterId":"ch_work_bckl_5","text":"〈實戰〉第四十四","sortOrder":11},
  {"id":"s_work_bckl_5_12","chapterId":"ch_work_bckl_5","text":"凡與敵戰，若敵人势實，我當嚴兵以備之，則敵人必不輕動。法曰：「實而備之。」","sortOrder":12},
  {"id":"s_work_bckl_5_13","chapterId":"ch_work_bckl_5","text":"三國，蜀先主為漢中王，拜關羽為前將軍，假節鉞，屯江陵。是歲，羽留兵屯公安、南郡，以備吳，而率兵攻魏將曹仁於樊。曹公遣於禁等救仁。秋，大雨，漢水泛溢，禁所督七軍皆没。禁降羽，庞德被誅。梁、郏、陆浑群盜等，或遙受羽印號，為支党，羽威震華夏。","sortOrder":13},
  {"id":"s_work_bckl_5_14","chapterId":"ch_work_bckl_5","text":"〈輕戰〉第四十五","sortOrder":14},
  {"id":"s_work_bckl_5_15","chapterId":"ch_work_bckl_5","text":"凡與敵戰，必須料敵詳審而後出兵。若不計而進，不謀而戰，則必為敵所败矣。法曰：「勇者必輕合，輕合而不知利。」","sortOrder":15},
  {"id":"s_work_bckl_5_16","chapterId":"ch_work_bckl_5","text":"春秋，晉文公與楚戰，知楚將子玉刚忿褊急，文公遂執其使者宛春以撓之。子玉怒，遂乘晉軍，楚軍大败。","sortOrder":16},
  {"id":"s_work_bckl_5_17","chapterId":"ch_work_bckl_5","text":"〈重戰〉第四十六","sortOrder":17},
  {"id":"s_work_bckl_5_18","chapterId":"ch_work_bckl_5","text":"凡與敵戰，必務持重，見利則動，不見利則止，慎不可輕舉也。若此，則必不陷於死地。法曰：「不動如山。」","sortOrder":18},
  {"id":"s_work_bckl_5_19","chapterId":"ch_work_bckl_5","text":"春秋，晉將栾書伐楚，將戰，楚晨壓晉軍而陣。軍吏患之，裨將范丏趨進曰：「塞井夷竈，陳於軍中，而疏行首。〔晉、楚唯天所授，何患焉？」文子執戈逐之，曰：「國之存亡，天也，童子何知焉？」〕栾書曰：「楚師輕佻，吾持重固壘以待之，三日必退。退而击之，必獲全勝。」〔至曰：「楚有六間，不可失也。其二卿相惡，王卒以舊，鄭陳而不整，蠻軍而不陳，陳不违晦，在陳而嚣，合而更嚣，各顧其後，莫有斗心；舊不必良，以犯天忌，我必克之。」〕公說。於是败楚師於鄢陵。","sortOrder":19},
  {"id":"s_work_bckl_5_20","chapterId":"ch_work_bckl_5","text":"〈利戰〉第四十七","sortOrder":20},
  {"id":"s_work_bckl_5_21","chapterId":"ch_work_bckl_5","text":"凡與敵戰，其將愚而不知变，可誘之以利。彼貪利而不知害，可設伏兵以击之，其軍可败。法曰：「利而誘之。」","sortOrder":21},
  {"id":"s_work_bckl_5_22","chapterId":"ch_work_bckl_5","text":"春秋，楚伐絞〔，軍其南門〕。莫敖屈瑕曰：「絞小而輕，輕則寡謀。請無捍采樵者以誘之。」從之。絞獲三十人。明日，絞人爭出，驅楚役徒於山中。楚人坐其北門，而伏諸山下，大败之。〔為城下之盟而還〕。","sortOrder":22},
  {"id":"s_work_bckl_5_23","chapterId":"ch_work_bckl_5","text":"〈害戰〉第四十八","sortOrder":23},
  {"id":"s_work_bckl_5_24","chapterId":"ch_work_bckl_5","text":"凡與敵各守疆界，若敵人寇抄我境，以扰邊民，可於要害處設伏兵，或筑障塞以邀之，敵必不敢輕犯。法曰：「能使敵人不得至者，害之也。」","sortOrder":24},
  {"id":"s_work_bckl_5_25","chapterId":"ch_work_bckl_5","text":"唐時，朔方軍總管沙矺忠義為突厥所败，詔張仁願攝御史大夫代之。既至，賊已出，率兵躡击，夜掩其營，破之。始，朔方軍與突厥以河為界，北崖有拂雲祠，突厥每犯邊，必先謁祠祷祀，然後引兵渡而南。時默啜悉兵西击突騎施，張仁願請乘虛取漠南，於河北筑三受降城，絕虜南寇路。唐休璟以為：「西漢以來，皆南守河，今筑城虜腹中，終為所有。」仁願固請，中宗許之。表留歲滿镇兵以助其功，時鹹陽兵二百人逃歸，仁願擒之，盡斬城下，軍中股栗，役者盡力，六旬而三城就。以拂雲為中城，南直朔方；西城南直靈武，東城南直榆林。三壘相距各四百餘里，其北皆大碛也，斥地三百里遠。又於牛頭朝那山北置烽候千八百所。自是突厥不敢逾山牧馬，朔方复無寇。歲省費亿計，减镇兵數萬。","sortOrder":25},
  {"id":"s_work_bckl_5_26","chapterId":"ch_work_bckl_5","text":"〈安戰〉第四十九","sortOrder":26},
  {"id":"s_work_bckl_5_27","chapterId":"ch_work_bckl_5","text":"凡敵人遠來氣銳，利於速戰；我深溝高壘，安守勿應，以待其敝。若彼以事撓我求戰，亦不可動。法曰：「安則靜。」","sortOrder":27},
  {"id":"s_work_bckl_5_28","chapterId":"ch_work_bckl_5","text":"三國，蜀將諸葛亮率眾十餘萬出斜穀，壘於渭水之南。魏遣大將司馬懿拒之，諸將欲往渭北以待之，懿曰：「百姓積聚皆在渭南，此必爭之地也。」遂率軍而濟，背水為壘。因謂諸將曰：「亮若勇者，當出武功，依山而東。若西上五丈原，則諸軍無事矣。」亮果上五丈原。會有長星墜亮之壘，懿知其必败。時魏王以亮率軍遠入，利在急戰，每命懿持重，以俟其变。亮數挑戰，懿不出，因遺懿以巾幗婦人之飾。懿終不出。懿弟子孚書問軍事，懿复曰；「亮志大而不見機，多謀少决，好兵而無權，雖持兵十萬，已墮吾畫中，破之必矣。」與之對壘百餘日，會亮病卒，諸將燒營遁走，百姓奔告，懿出兵追之。亮長史楊儀反旗鳴鼓，若將向懿者。懿以歸師不之迫，於是楊儀結陣而去。經日，行其營壘，觀其遺事，獲其圖書、糧食甚眾。懿審其必死，曰：「天才奇才也！」辛毗以為尚未可知。懿曰：「軍家所重，軍書密計、兵馬糧食，今皆弃之，豈有人損其五臟而可以生乎？宜急追之。」關中多蒺藜，懿使軍士三千人著软材平底木履前行，蒺藜著履，然後馬步俱進。追到赤岸，乃知亮已死。時百姓為之諺曰：「死諸葛能走生仲達。」懿笑曰：「吾能料生，不能料死故也。」","sortOrder":28},
  {"id":"s_work_bckl_5_29","chapterId":"ch_work_bckl_5","text":"〈危戰〉第五十","sortOrder":29},
  {"id":"s_work_bckl_5_30","chapterId":"ch_work_bckl_5","text":"凡與敵戰，若陷在危亡之地，當激励將士决死而戰，不可懷生，則勝。法曰：「兵士甚陷，則不懼。」","sortOrder":30},
  {"id":"s_work_bckl_5_31","chapterId":"ch_work_bckl_5","text":"後漢將吳漢讨公孫述，進入犍為界。諸縣皆城守。漢攻廣都，拔之。遣輕騎燒成都市桥，武陽以東諸小城皆降。帝戒漢曰：「成都十餘萬眾，不可輕也。但堅據廣都，待其來攻，勿與爭鋒。若不敢來，公須轉營迫之，須其力疲，乃可击也。」漢不聽，乘利遂自將步騎二萬餘人進逼成都，去城十餘里，阻江北為營，作浮桥，使別將劉尚將萬餘人屯於江南，相去二十餘里。帝大驚，责漢曰：「比敕公千條萬端，何意臨事悖亂？既輕敵深入，又與尚別營，事有缓急，不复相及。賊若出兵缀公，以大眾攻尚，尚破，公即败矣。幸無他者，急率兵還廣都。」詔書未到，述果遣其將謝丰、袁吉將眾十餘萬出攻漢；使別將將萬餘人劫劉尚，令不得相救。漢與大戰一日，兵败走入壁，丰围之。漢召諸將厲之曰：「吾與諸將逾越险阻，轉戰千里，所在斬獲，遂深入敵地，今至城下，而與尚二處受围，势既不接，其禍難量。欲潛師就尚於江南御之。若能同心协力，人自為戰，大功可立，如其不然，败必無餘。成败之機，在此一舉。」諸將皆曰：「诺。」於是，饗士秣馬，閉營三日不出，乃多立幡旗，使煙火不絕，夜衔枚引兵與尚合軍。丰等不覺，明日，乃分兵拒江北，自將攻江南。漢悉兵迎戰，自旦至哺，遂大败之，斬謝丰、袁吉。於是，率兵還廣都，留劉尚拒述，具以状聞，而深自譴责。帝報曰：「公還廣都，甚得其宜，述必不敢略尚而击公。若先攻尚，公從廣都五十里悉步騎赴之，適當值其危困，破之必矣。」於是，漢與述戰於廣都、成都之間，八戰八克，遂軍於郭中。述自將數萬人出城大戰，漢使護軍高午、唐邯將銳卒數萬击之。述兵败走，高午奔陣刺述，殺之。旦日城降，斬述首傳送洛陽。蜀遂平。","sortOrder":31},
  {"id":"s_work_bckl_5_32","chapterId":"ch_work_bckl_5","text":"〔《百戰奇略》卷五終〕","sortOrder":32},
  {"id":"s_work_bckl_6_1","chapterId":"ch_work_bckl_6","text":"卷之六","sortOrder":1},
  {"id":"s_work_bckl_6_2","chapterId":"ch_work_bckl_6","text":"〈生戰〉第五十一","sortOrder":2},
  {"id":"s_work_bckl_6_3","chapterId":"ch_work_bckl_6","text":"凡與敵戰，若地利已得，士卒已陣，法令已行，奇兵已設，要當割弃性命而戰，則勝。若為將臨陣畏怯，欲要生，反為所殺。法曰：「幸生則死。」","sortOrder":3},
  {"id":"s_work_bckl_6_4","chapterId":"ch_work_bckl_6","text":"春秋時，楚子伐鄭，晉師救之，與戰於敖、鄗之間。晉趙婴齊使其徒先具舟於河，欲败而先濟，故將士懈，卒不可勝。","sortOrder":4},
  {"id":"s_work_bckl_6_5","chapterId":"ch_work_bckl_6","text":"〈死戰〉第五十二","sortOrder":5},
  {"id":"s_work_bckl_6_6","chapterId":"ch_work_bckl_6","text":"凡敵人強盛，吾士卒疑惑，未肯用命，須置之死地，告令三軍，示不獲已。殺牛燔車，以享戰士，燒弃糧食，填夷井竈，焚舟破釜，絕去其生慮，則必勝。法曰：「必死則生。」","sortOrder":6},
  {"id":"s_work_bckl_6_7","chapterId":"ch_work_bckl_6","text":"秦將章邯已破楚將項梁軍，以為楚地兵不足忧，乃渡河击趙，大破之。當此時，趙歇為王，陳餘為將，張耳為相，兵败皆走入鉅鹿城。章邯令王離、涉閒围鉅鹿，章邯軍其南，筑甬道而输之粟。楚懷王以宋義為上將，項羽為次將，范增為裨將，救趙。諸別將皆屬焉。宋義行至安陽，留四十餘日不進，遣其子宋襄相齊，自送之無鹽，飲酒高會。項羽曰：「今國兵新破，王坐不安席，扫境內而专諸將軍，國家安危，在此一舉。今不恤士卒而徇其私，非社稷之臣。」項羽晨朝宋義，即其帳中，斬之，下令軍中曰：「宋義與齊謀反，楚王陰令羽誅之。」是時，諸將皆慑服，莫敢支吾，皆曰：「首立楚者，將軍家也。今將軍誅叛亂。」即共立羽為假上將軍。使人追宋義子襄，及之齊，殺之。使桓楚報命於楚懷王，因命項羽為上將軍。當陽君、蒲將軍皆屬焉。項羽以殺宋義，威震楚國，名聞諸侯。乃遣當陽君、蒲將軍率二萬眾渡河救鉅鹿。戰少利，陳餘复請兵，項羽乃悉兵渡河，沉舟，破釜甑，燒庐舍，持三日糧，以示士卒必死，無還心。於是至則围王離，與秦軍遇，九戰，絕其甬道，大破之，殺蘇角，虜王離。當是時，楚兵冠諸侯，諸侯救鉅鹿下者十餘壁，莫敢縱兵。及楚兵击秦軍，諸侯皆從壁上觀。楚戰士無不以一當十，楚兵呼聲動天地，諸侯〔軍無不〕人人惴恐。於是，大破秦軍。","sortOrder":7},
  {"id":"s_work_bckl_6_8","chapterId":"ch_work_bckl_6","text":"〈飢戰〉第五十三","sortOrder":8},
  {"id":"s_work_bckl_6_9","chapterId":"ch_work_bckl_6","text":"凡興兵征讨，深入敵地，刍糧乏闕，必須分兵抄掠，據其仓廪，奪其蓄積，以繼軍餉，則勝。法曰：「因糧於敵，故軍食可足也。」","sortOrder":9},
  {"id":"s_work_bckl_6_10","chapterId":"ch_work_bckl_6","text":"《北史》：北周將贺若敦率兵渡江取陳湘州。陳將侯瑱讨之。秋水泛濫，江路遂斷。糧援既絕，人懷危懼。敦於是分兵抄掠，以充資費。恐瑱等知其糧少，乃於營內多聚土，覆之以米。召侧近村人，佯有訪問，隨即遣之。瑱等聞之，以糧為實。敦又增修營壘，造庐舍，示以持久。湘、羅之間，遂废農業。瑱等無如之何。初，土人乘輕船，載米粟及籠雞鸭以餉瑱軍。敦患之，乃伪為土人船，伏兵甲於中。瑱軍望見，謂餉船至，逆水爭取。敦甲士遂擒之。又敦軍數有叛者乘馬投瑱，瑱辄納之。敦乃取一馬，牵以趣船，令船中人以鞭鞭之。如是者再，馬畏船不敢上。後伏兵於江岸，使人乘畏船馬诈投瑱軍，瑱即遣兵迎接，爭來牵馬。馬既畏船不上，伏兵發，盡殺之。後實有饋餉及亡奔瑱者，猶恐敦設诈，兵不敢受。相持歲餘，瑱不能製。","sortOrder":10},
  {"id":"s_work_bckl_6_11","chapterId":"ch_work_bckl_6","text":"〈飽戰〉第五十四","sortOrder":11},
  {"id":"s_work_bckl_6_12","chapterId":"ch_work_bckl_6","text":"凡敵人遠來，糧食不繼，敵飢我飽，可堅壁不戰，持久以敝之，絕其糧道。彼退走，密遣奇兵，邀其歸路，縱兵追击，破之必矣。法曰：「以飽待飢。」","sortOrder":12},
  {"id":"s_work_bckl_6_13","chapterId":"ch_work_bckl_6","text":"唐武德初，劉武周據太原，使其將宋金刚屯於河東。太宗往征之，謂諸將曰：「金刚垂軍千里入吾地，精兵驍將皆在於此。武周自據太原，专寄金刚以為捍蔽。金刚雖眾，內實空虛，虜掠為資，意在速戰。我當堅營待其飢，未宜速戰。」於是，遣劉洪等絕其糧道，其眾遂餒，金刚乃遁。","sortOrder":13},
  {"id":"s_work_bckl_6_14","chapterId":"ch_work_bckl_6","text":"〈勞戰〉第五十五","sortOrder":14},
  {"id":"s_work_bckl_6_15","chapterId":"ch_work_bckl_6","text":"凡與敵戰，若便利之地，敵先結陣而據之，我後去趨戰，則我勞而為敵所勝。法曰：「後處戰地而趨戰者勞。」","sortOrder":15},
  {"id":"s_work_bckl_6_16","chapterId":"ch_work_bckl_6","text":"晉司空劉琨遣將軍姬澹率兵十餘萬讨石勒。勒將拒之，或諫曰：「澹兵馬精盛，其鋒不可當，且深溝高壘以挫其銳，攻守势異，必獲萬全。」勒曰：「澹軍遠來，體疲力竭，犬馬乌合，號令不齊，一戰可擒也，何強之有！援又垂至，胡可舍去，大軍一動，豈易中還！若澹乘我之退，顧乃無暇，焉得深溝高壘乎！此謂不戰而自取滅亡之道。」遂斬諫者。以孔萇為前鋒都督，令三軍後出者斬。設疑兵於山下，分為二伏。勒率兵與澹戰，伪收眾而北。澹縱兵追之，〔勒前後〕伏發，夹击，澹大败而退。","sortOrder":16},
  {"id":"s_work_bckl_6_17","chapterId":"ch_work_bckl_6","text":"〈佚戰〉第五十六","sortOrder":17},
  {"id":"s_work_bckl_6_18","chapterId":"ch_work_bckl_6","text":"凡與敵戰，不可恃己勝而放佚，當益加嚴厲以待敵，佚而猶勞。法曰：「有備無患。」","sortOrder":18},
  {"id":"s_work_bckl_6_19","chapterId":"ch_work_bckl_6","text":"秦王翦將兵六十萬代李信击荆。荆聞王翦益軍而來，乃悉國中兵以拒秦。王翦至，堅壁而守之，不肯戰。荆兵數出挑戰，終不出。王翦日休士，洗沐而善飲食撫循之，親與士卒同食。久之，王翦使人問：「軍中戲乎？」對曰：「方投石超距。」於是，王翦曰：「士卒可用。」荆數挑戰而秦不出，乃引而東。翦因舉兵追之，令壮士出击，大破荆軍。","sortOrder":19},
  {"id":"s_work_bckl_6_20","chapterId":"ch_work_bckl_6","text":"〈勝戰〉第五十七","sortOrder":20},
  {"id":"s_work_bckl_6_21","chapterId":"ch_work_bckl_6","text":"凡與敵戰，若我勝彼負，不可驕惰，當日夜嚴備以待之。敵人雖來，有備無害。法曰：「既勝若否。」","sortOrder":21},
  {"id":"s_work_bckl_6_22","chapterId":"ch_work_bckl_6","text":"秦二世時，項梁使沛公、項羽別攻城陽，屠之。西破秦軍濮陽東，秦收兵入濮陽。沛公、項羽乃攻定陶，因西略地至雍丘，大破秦軍，斬李由，還攻外黃。項梁益輕秦，有驕色。宋義進諫於梁曰：「戰勝而將驕卒惰者败。今兵少惰矣，而秦兵日益，臣為君畏之。」梁弗聽。而使宋義〔使〕於齊。道遇齊使者高陵君顯，曰：「公將見武信君乎？」曰：「然。」曰：「今武信君必败，公徐行即免死，疾行則及禍。」秦果悉兵益章邯击楚軍，大败之，項梁死。","sortOrder":22},
  {"id":"s_work_bckl_6_23","chapterId":"ch_work_bckl_6","text":"〈败戰〉第五十八","sortOrder":23},
  {"id":"s_work_bckl_6_24","chapterId":"ch_work_bckl_6","text":"凡與敵戰，若彼勝我負，未可畏怯，須思害中之利，當整励器械，激扬士卒，候彼懈怠而击之，則勝。法曰：「因害而患可解也。」","sortOrder":24},
  {"id":"s_work_bckl_6_25","chapterId":"ch_work_bckl_6","text":"晉末，河間王顒在關中，遣張方讨長沙王義，率眾自函穀人屯河南。惠帝遣左將軍皇甫商拒之，方潛軍破商，遂入洛陽。又奉帝命讨方於城內，方軍望見乘舆，於是少却，方止之不可得，眾遂大败，殺傷滿衢巷。方退壁於十三里桥，人情挫衄，無复固志，多勸方夜遁。方曰：「兵之利钝是常事，貴因败以為成耳。我更前作壘，出其不意，此兵法之奇也。」乃夜潛進逼洛陽城七里。義既新捷，不以為意，忽聞方壘成，乃出戰，遂大败而還。","sortOrder":25},
  {"id":"s_work_bckl_6_26","chapterId":"ch_work_bckl_6","text":"〈進戰〉第五十九","sortOrder":26},
  {"id":"s_work_bckl_6_27","chapterId":"ch_work_bckl_6","text":"凡與敵戰，若審知敵人有可勝之理，則宜速進兵以捣之，無有不勝。法曰：「見可則進。」","sortOrder":27},
  {"id":"s_work_bckl_6_28","chapterId":"ch_work_bckl_6","text":"唐，李靖為定襄道行軍總管，击破突厥，頡利可汗走保鐵山，遣使入朝謝罪，請舉國歸附。以靖往迎之。頡利雖外請朝謁，而內懷遲疑。靖揣知其意。時詔鸿臚卿唐俭等慰諭之。靖謂副將張公謹曰：「詔使到彼，虜必自安。若萬騎赉二十日糧，自白道袭之，必得所欲。」公謹曰：「上已與約降，行人在彼，奈何？」靖曰：「機不可失，韓信所以破齊也。如唐俭辈何足惜哉！」督兵疾進，行至陰山，遇其斥候千餘，皆俘以隨軍。頡利見使者大悅，不虞官兵〔至也〕。靖前鋒乘霧而行，去其牙帳七里，虜始覺，列兵未及陣，靖縱兵击之，斬首萬餘級，俘男女十餘萬，擒其子叠羅施，殺義成公主。頡利亡去，為大同道行軍副總管張寶相擒以獻。於是，斥地自陰山北至大漠矣。","sortOrder":28},
  {"id":"s_work_bckl_6_29","chapterId":"ch_work_bckl_6","text":"〈退戰〉第六十","sortOrder":29},
  {"id":"s_work_bckl_6_30","chapterId":"ch_work_bckl_6","text":"凡與敵戰，若敵眾我寡，地形不利，力不可爭，當急退以避之，可以全軍。法曰：「知難而退。」","sortOrder":30},
  {"id":"s_work_bckl_6_31","chapterId":"ch_work_bckl_6","text":"三國，魏將曹爽伐蜀，司馬昭同行出骆穀，次於興势。蜀將王平乘夜袭击，昭令堅臥不動，平退。昭謂諸將曰：「費禕據险拒守，進不獲戰，攻之不可，宜急旋軍，以為後圖。」爽等遂退，禕果馳兵趨三嶺爭险，爽等潛師越险，乃得退。","sortOrder":31},
  {"id":"s_work_bckl_6_32","chapterId":"ch_work_bckl_6","text":"〔《百戰奇略》卷六終〕","sortOrder":32},
  {"id":"s_work_bckl_7_1","chapterId":"ch_work_bckl_7","text":"卷之七","sortOrder":1},
  {"id":"s_work_bckl_7_2","chapterId":"ch_work_bckl_7","text":"〈挑戰〉第六十一","sortOrder":2},
  {"id":"s_work_bckl_7_3","chapterId":"ch_work_bckl_7","text":"凡與敵戰，營壘相遠，势力相均，可輕騎挑攻之，伏兵以待之，其軍可破。若敵用此謀，我不可以全氣击之。法曰：「遠而挑戰，欲人之進也。」","sortOrder":3},
  {"id":"s_work_bckl_7_4","chapterId":"ch_work_bckl_7","text":"十六國，姚襄據黃落，苻生遣將苻黃眉、邓羌等率步騎〔萬五千〕讨襄。襄深溝高壘，固守不戰。邓羌曰：「襄性刚愎，易以撓動。若長驅一行，直壓其壘，襄必忿而出戰，可一戰而擒也。」黃眉從之，遣羌率騎三千軍於壘門。襄怒，盡銳出戰。羌伪不勝，率騎而退，襄追之於三原，羌回〔騎〕拒襄，〔俄〕而黃眉至，大戰，斬之，〔盡〕俘其眾〔，黃眉等振旅而歸〕。","sortOrder":4},
  {"id":"s_work_bckl_7_5","chapterId":"ch_work_bckl_7","text":"〈致戰〉第六十二","sortOrder":5},
  {"id":"s_work_bckl_7_6","chapterId":"ch_work_bckl_7","text":"凡致敵來戰，則彼势常虛；不能赴戰，則我势常實。多方以致敵之來，我據便地而待之，無有不勝。法曰：「致人而不致於人。」","sortOrder":6},
  {"id":"s_work_bckl_7_7","chapterId":"ch_work_bckl_7","text":"後漢建武五年，光武詔耿弇，悉收集降附，結部曲，置將吏，弇帥騎都尉劉歆、泰山太守陳俊將兵而東。張步聞之，使其將費邑軍歷下，又令兵屯祝阿，別於泰山、鐘城列營數十以待之。渡河先击祝阿，拔之，故开围一角，令其眾得奔歸鐘城。〔鐘城〕人聞祝阿已潰，大恐，遂空壁亡去。費邑分兵，遣其弟費敢守巨里，弇進兵先胁巨里，嚴令軍中趣修攻具〔，宣敕諸部〕：後三日悉力攻巨里城。陰缓生口，〔令得〕亡歸，以弇期告邑。邑至日果自將精兵〔三萬餘人〕來救〔之〕。弇謂諸將曰：「吾所以修攻具者，欲誘致之耳。野兵不击，何以城為？」則分兵守巨里，自帥精銳上岡阪，乘高合戰，大破之，斬邑。既而取首級以示巨里，城中懼，費敢〔悉眾〕亡歸張步。弇悉收其積聚，縱兵攻諸未下者，平四十餘營，遂定濟南。","sortOrder":7},
  {"id":"s_work_bckl_7_8","chapterId":"ch_work_bckl_7","text":"〈遠戰〉第六十三","sortOrder":8},
  {"id":"s_work_bckl_7_9","chapterId":"ch_work_bckl_7","text":"凡與敵阻水相拒，我欲遠渡，可多設舟楫，示之若近濟，則敵必併眾應之，我出其空虛以濟。如無舟楫，可用竹木、蒲苇、罌缶、瓮囊、槍杆之屬，缀為排筏，皆可濟渡。法曰：「遠而示之近。」","sortOrder":9},
  {"id":"s_work_bckl_7_10","chapterId":"ch_work_bckl_7","text":"漢初，魏王豹初降漢，复以親疾請歸，至國，即絕其河關，反與楚約和。漢王遣郦生往說豹，不聽。漢王以韓信為左丞相击豹。〔魏王〕盛兵蒲阪，塞臨晉；信乃益為疑兵，陳船欲渡臨晉，而引兵從夏陽以木罌渡軍，袭安邑。魏王豹驚，帥兵迎戰，信遂虜豹，定魏〔，為河東郡〕。","sortOrder":10},
  {"id":"s_work_bckl_7_11","chapterId":"ch_work_bckl_7","text":"〈近戰〉第六十四","sortOrder":11},
  {"id":"s_work_bckl_7_12","chapterId":"ch_work_bckl_7","text":"凡與敵夹水為陣，我欲攻近，反示以遠，須多設疑兵，上下遠渡，敵必分兵來應，我可以潛師近袭之，其軍可破。法曰：「近而示之遠。」","sortOrder":12},
  {"id":"s_work_bckl_7_13","chapterId":"ch_work_bckl_7","text":"春秋，越人伐吳，吳人御之笠泽，夹水而陣。越人為左右陣，夜鼓噪而進，吳師分以御之。越子以三軍潛涉，當吳中兵而鼓之。吳軍大败，遂至滅亡。","sortOrder":13},
  {"id":"s_work_bckl_7_14","chapterId":"ch_work_bckl_7","text":"〈水戰〉第六十五","sortOrder":14},
  {"id":"s_work_bckl_7_15","chapterId":"ch_work_bckl_7","text":"凡與敵戰，或岸邊為陣，或水上泊舟，皆謂之水戰。若近水為陣者，須去水稍遠，一則誘敵使渡，一則示敵無疑。我欲必戰，勿近水迎敵，恐其不得渡；我欲不戰，則拒水阻之，使敵不得濟。若敵率兵渡水來戰，可於水邊伺其半濟而击之，則利。法曰：「涉水半渡可击。」","sortOrder":15},
  {"id":"s_work_bckl_7_16","chapterId":"ch_work_bckl_7","text":"漢郦生說齊下之，齊王日與生縱酒為樂，而罢守備。蒯通說信，遂渡河，袭破齊。齊王以郦生賣己，烹之，而走高密，請救於楚。楚遣龍且將兵救齊。或〔說龍且〕曰：「漢兵遠來，其鋒難當，齊、楚自居其地，兵易败散。不如深壁，令齊王使其信臣招所亡城，聞其王在，楚來救，必反漢。漢兵客居，其势無所食，可不戰而擒也。」龍且曰：「吾知韓信為人，易與耳。今若救齊不戰而降之，有何功？若戰而勝，齊半可得。」遂進兵與漢軍夹濰水而陣。信夜使人囊沙壅水上流，旦渡击且，佯败走。龍且喜曰：「吾固知信怯。」遂追之。信使人决壅囊，水大至，且軍大半不得渡，即击，殺且。〔龍且〕水東軍散走，〔齊王廣〕亡去〔。信遂追北至城陽，皆虜楚卒〕，遂平齊。","sortOrder":16},
  {"id":"s_work_bckl_7_17","chapterId":"ch_work_bckl_7","text":"〈火戰〉第六十六","sortOrder":17},
  {"id":"s_work_bckl_7_18","chapterId":"ch_work_bckl_7","text":"凡戰，若敵人居近草莽，營舍茅竹，積刍聚糧，天時燥旱，因風縱火以焚之，選精兵以击之，其軍可破。法曰：「行火必有因。」","sortOrder":18},
  {"id":"s_work_bckl_7_19","chapterId":"ch_work_bckl_7","text":"漢靈帝中平元年，皇甫嵩讨黃巾，漢將朱雋與賊波才戰，败，賊遂围嵩於長社。賊依草結營，會大風。嵩敕軍束苣乘城，使銳卒間出围外，縱火大呼，城上舉燎應之，嵩因鼓而奔其陣，賊驚亂奔走。會帝遣曹操將兵適至，合戰大破之，斬首數萬級。","sortOrder":19},
  {"id":"s_work_bckl_7_20","chapterId":"ch_work_bckl_7","text":"〈缓戰〉第六十七","sortOrder":20},
  {"id":"s_work_bckl_7_21","chapterId":"ch_work_bckl_7","text":"凡攻城之法，最為下策，不得已而為之。所謂三月修器械，三月成距堙者，六月也。謂戒為己者，忿躁不待攻具而令士卒蚁附，恐傷人之多故也。若彼城高池深，多人而少糧，外無救援，可羁縻取之，則利。法曰：「其徐如林。」","sortOrder":21},
  {"id":"s_work_bckl_7_22","chapterId":"ch_work_bckl_7","text":"十六國，前燕將慕容恪击段龛於廣固，围之。諸將請恪急攻，恪曰：「軍势有宜缓以克敵，有宜急而取之。若彼我势均，外有強援，恐有腹背之患，則攻之不得不速。若我強彼弱，外無救援，當羁縻守之，以待其敝。兵法：十围五攻。正謂此也。龛党尚眾，未有離心。今凭阻堅城，上下戮力，盡銳攻之，數旬可拔，然殺吾士卒必多矣。當持久以取耳。」乃為壁壘以守之，終克廣固。","sortOrder":22},
  {"id":"s_work_bckl_7_23","chapterId":"ch_work_bckl_7","text":"〈速戰〉第六十八","sortOrder":23},
  {"id":"s_work_bckl_7_24","chapterId":"ch_work_bckl_7","text":"凡攻城围邑，若敵糧多人少，外有救援，可以速攻，則勝。法曰：「兵貴拙速。」","sortOrder":24},
  {"id":"s_work_bckl_7_25","chapterId":"ch_work_bckl_7","text":"三國，蜀將孟達降魏，遂領新城太守，未幾，复連吳附蜀以叛魏。司馬懿潛軍進讨，諸將言達與蜀交結，宜觀望而後可。懿曰：「達無信義，此其相疑之時，當及其未定，促而决之。」乃倍道兼行，〔八日〕至其城下。吳、蜀各遣將救達，懿乃分兵拒之。初，達與諸葛亮書曰：「宛去洛八百里，去吾一千二百里，聞吾舉事，表上天子，比相往反時，一月間也，則吾城已固，諸將足辦。吾所在深险，司馬公必不自來；諸將來，吾無患矣。」及兵到，達又告亮曰：「吾舉事八日，而兵至城下，何其神速也。」上庸城三面阻水，達於外為木柵以自固。懿渡水，破其柵，直造城下，〔八道攻之〕，旬有六日，李辅等斬達首，开門以降。","sortOrder":25},
  {"id":"s_work_bckl_7_26","chapterId":"ch_work_bckl_7","text":"〈整戰〉第六十九","sortOrder":26},
  {"id":"s_work_bckl_7_27","chapterId":"ch_work_bckl_7","text":"凡與敵戰，若敵人行陣整齊，士卒安靜，未可輕戰，伺其变動击之，則利。法曰：「無邀正正之旗。」","sortOrder":27},
  {"id":"s_work_bckl_7_28","chapterId":"ch_work_bckl_7","text":"三國，魏司馬懿征公孫淵，〔次於遼水。淵遣步騎數萬，阻遼隧，堅壁而守，以距帝。〕懿泛舟潛濟遼水，〔傍遼水〕作〔長〕围，弃城而向襄平。諸將曰：「不攻城而作围，非所以示眾也。」懿曰：「賊堅營高壘，欲以老吾軍也。攻之，正墮其計。賊大眾在此，其巢穴虛失，我直指襄平，必人懷內懼，懼而求戰，破之必矣。」遂整陣而過。賊見兵出其後，果邀之，乃縱兵逆击，大破之。","sortOrder":28},
  {"id":"s_work_bckl_7_29","chapterId":"ch_work_bckl_7","text":"〈亂戰〉第七十","sortOrder":29},
  {"id":"s_work_bckl_7_30","chapterId":"ch_work_bckl_7","text":"凡與敵戰，若敵人行陣不整，士卒喧哗，宜急出兵以击之，則利。法曰：「亂而取之。」","sortOrder":30},
  {"id":"s_work_bckl_7_31","chapterId":"ch_work_bckl_7","text":"唐，段志玄從劉文靜拒屈突通於潼關，文靜為通將桑顯和所败，軍營已潰，志玄率二十騎赴之，击殺數十人而還；還為流矢中足，慮眾心動，忍而不言，更入賊陣者再三。顯和軍亂，大軍因而复振，击大破之。〔及屈突通之遁，志玄與諸將追而擒之。〕","sortOrder":31},
  {"id":"s_work_bckl_7_32","chapterId":"ch_work_bckl_7","text":"〔《百戰奇略》卷七終〕","sortOrder":32},
  {"id":"s_work_bckl_8_1","chapterId":"ch_work_bckl_8","text":"卷之八","sortOrder":1},
  {"id":"s_work_bckl_8_2","chapterId":"ch_work_bckl_8","text":"〈分戰〉第七十一","sortOrder":2},
  {"id":"s_work_bckl_8_3","chapterId":"ch_work_bckl_8","text":"凡與敵戰，若我眾敵寡，當擇平易宽廣之地以勝之。若五倍於敵，則三術為正，二術為奇；三倍於敵，二術為正，一術為奇。所謂一以當其前，一以攻其後。法曰：「分不分為縻軍。」","sortOrder":3},
  {"id":"s_work_bckl_8_4","chapterId":"ch_work_bckl_8","text":"梁將陳霸先、王僧辯讨侯景，軍於張公洲。高旗巨艦，截江蔽空，乘潮順流。景登石頭，望之不悅，曰：「彼軍士有如是之氣，不可易也。」帥鐵騎萬人，鳴鼓而前。霸先謂僧辯曰：「善用兵者，如常山之蛇，首尾相應。賊今送死，欲為一戰。我眾彼寡，宜分其势。」僧辯從之，以劲弩當其前，輕銳蹂其後，大陣冲其中。景遂大潰，弃城而走。","sortOrder":4},
  {"id":"s_work_bckl_8_5","chapterId":"ch_work_bckl_8","text":"〈合戰〉第七十二","sortOrder":5},
  {"id":"s_work_bckl_8_6","chapterId":"ch_work_bckl_8","text":"凡兵散則势弱，聚則势強，兵家之常情也。若我兵分屯數處，敵若以眾攻我，當合軍以击之。法曰：「聚不聚為孤旅。」","sortOrder":6},
  {"id":"s_work_bckl_8_7","chapterId":"ch_work_bckl_8","text":"开元時，吐蕃入寇，報新城之役，晨壓官軍，眾寡不敵，師人皆懼焉。王忠嗣策馬而進，左右馳突，如此無不辟易，出而复合，殺數百人，賊眾遂亂。三軍翼而击之，吐蕃大败。","sortOrder":7},
  {"id":"s_work_bckl_8_8","chapterId":"ch_work_bckl_8","text":"〈怒戰〉第七十三","sortOrder":8},
  {"id":"s_work_bckl_8_9","chapterId":"ch_work_bckl_8","text":"凡與敵戰，須激励士卒，使忿怒而後出戰。法曰：「殺敵者，怒也。」","sortOrder":9},
  {"id":"s_work_bckl_8_10","chapterId":"ch_work_bckl_8","text":"漢光武建武四年，詔將軍王霸、馬武讨周建於垂惠。蘇茂將兵四千餘救建，先遣精騎遮击馬武軍糧，武往救之。建於城中出兵夹击武，武恃霸援，戰不甚力，為茂、建所败，過霸營，大呼求救。霸曰：「賊兵势盛，出必兩败，努力而已。」乃閉營堅壁。軍吏皆爭之。霸曰：「茂兵精銳，其眾又多，吾吏士心恐，而捕虜與吾相恃，兩軍不一，败道也。今閉營堅守，示不相救，彼必乘势輕進；武恨無救，則其戰當自倍。如此，茂眾疲勞，吾乘其敝，乃可克也。」茂、建果悉兵出攻武，合戰良久，霸軍中壮士數十人斷發請戰。霸乃开營後，大叱出精騎袭其背。茂、建前後受敵，遂败走之。","sortOrder":10},
  {"id":"s_work_bckl_8_11","chapterId":"ch_work_bckl_8","text":"〈氣戰〉第七十四","sortOrder":11},
  {"id":"s_work_bckl_8_12","chapterId":"ch_work_bckl_8","text":"夫將之所以戰者，兵也；兵之所以戰者，氣也；氣之所以盛者，鼓也。能作士卒之氣，則不可太頻，太頻則氣易衰；不可太遠，太遠則力易竭。須度敵人之至六七十步之內，乃可以鼓，令士卒進戰。彼衰我盛，败之必矣。法曰：「氣實則斗，氣奪則走。」","sortOrder":12},
  {"id":"s_work_bckl_8_13","chapterId":"ch_work_bckl_8","text":"春秋，齊師伐魯，莊公將戰，曹刿請從，公與之同乘，戰於長勺。公將鼓之，刿曰：「未可。」齊人三鼓。刿曰：「可矣。」鼓之，齊師败績。〔公將馳之，刿曰：「未可。」下，视其轍，登軾而望之，曰：「可矣。」遂逐齊師。既克，〕公問其故。刿對曰：「夫戰，勇氣也。一鼓作氣，再而衰，三而竭。彼竭我盈，是以败之。」〔夫大國，難测也，懼有伏焉。吾视其轍亂，望其旗靡，故逐之。〕","sortOrder":13},
  {"id":"s_work_bckl_8_14","chapterId":"ch_work_bckl_8","text":"〈逐戰〉第七十五","sortOrder":14},
  {"id":"s_work_bckl_8_15","chapterId":"ch_work_bckl_8","text":"凡追奔逐北，須審真伪。若旗齊鼓應，號令如一，紛紛紜紜，雖退走，非败也，必有奇也，須當慮之。若旗參差而不齊，鼓大小而不應，號令喧嚣而不一，此真败却也，可以力逐。法曰：「凡從勿怠，敵人或止於路，則慮之。」","sortOrder":15},
  {"id":"s_work_bckl_8_16","chapterId":"ch_work_bckl_8","text":"唐武德元年，太宗征薛仁杲，其將宗羅[日侯]拒之，大破於淺水原。太宗帥騎追之，直趨折[土庶]围之。仁杲將多臨陣來降，复還取馬，太宗縱遣之。須臾，各乘馬至。太宗具知仁杲虛實，乃進兵合围。縱辯士喻以禍福，仁杲遂降。諸將皆贺，因問曰：「大王破敵，乃舍步兵，又無攻具，經薄城下，鹹疑不克，而卒下之，何也？」太宗曰：「此權道〔迫之，使其計不暇發，以故克〕也。且羅[日侯]所將皆隴外人，吾雖破之，然斬獲不多。若缓之，則皆入城，仁杲收而撫之，未易克也；迫之，則兵散隴外，折[土庶]自虛，仁杲破胆，不暇為謀，所以懼而降也。」","sortOrder":16},
  {"id":"s_work_bckl_8_17","chapterId":"ch_work_bckl_8","text":"〈歸戰〉第七十六","sortOrder":17},
  {"id":"s_work_bckl_8_18","chapterId":"ch_work_bckl_8","text":"凡與敵相攻，若敵無故退歸，必須審察，果力疲糧竭，可選輕銳躡之。若是歸師，則不可遏也。法曰：「歸師勿遏。」","sortOrder":18},
  {"id":"s_work_bckl_8_19","chapterId":"ch_work_bckl_8","text":"漢獻帝建安三年，曹操围張繡於穰。劉表遣兵救之，繡欲安眾守险，以絕軍後。操軍不得進，前後受敵，夜乃凿险〔為地道〕伪遁，伏兵以待。繡悉兵來追，操縱奇兵夹攻，大败之。謂荀彧曰：「虜遏我歸師，而與吾死地戰，吾是以知勝矣。」","sortOrder":19},
  {"id":"s_work_bckl_8_20","chapterId":"ch_work_bckl_8","text":"〈不戰〉第七十七","sortOrder":20},
  {"id":"s_work_bckl_8_21","chapterId":"ch_work_bckl_8","text":"凡戰，若敵眾我寡，敵強我弱，兵势不利；彼或遠來，糧餉不絕，皆不可與戰，宜堅壁持久以敝之，則敵可破。法曰：「不戰在我。」","sortOrder":21},
  {"id":"s_work_bckl_8_22","chapterId":"ch_work_bckl_8","text":"唐武德中，太宗帥兵渡河東讨劉武周。江夏王李道宗時年十七，從軍，與太宗登玉壁城觀賊陣，顧謂道宗曰：「賊恃其眾，來邀我戰，汝謂如何？」對曰：「群賊鋒不可當，易以計屈，難以力爭。今深溝高壘，以挫其鋒，乌合之徒，莫能持久，糧運將竭，當自離散，可不戰而擒也。」太宗曰：「汝見識與我相合。」後果食盡夜遁，追入介州，一戰败之。","sortOrder":22},
  {"id":"s_work_bckl_8_23","chapterId":"ch_work_bckl_8","text":"〈必戰〉第七十八","sortOrder":23},
  {"id":"s_work_bckl_8_24","chapterId":"ch_work_bckl_8","text":"凡興師深入敵境，若彼堅壁不與我戰，欲老我師，當攻其君主，捣其巢穴，截其歸路，斷其糧草，彼必不得已而須戰，我以銳卒击之，可败。法曰：「我欲戰，敵雖深溝高壘，不得不與我戰者，攻其所必救也。」","sortOrder":24},
  {"id":"s_work_bckl_8_25","chapterId":"ch_work_bckl_8","text":"三國，魏明帝景初二年，召司馬懿於長安，使將兵往遼東讨公孫淵。帝曰：「四千里征伐，雖雲用奇，亦當任力，不當稍計役費。度淵以何計得策？」懿曰：「弃城預走，上計也；〔據遼水以〕拒大軍，其次也；坐守襄平，此成擒耳。」曰：「三者何出？」懿曰：「唯明君能量彼我，預有所弃，此非淵所及也。」曰：「往還幾日？」對曰：「往百日，還百日，攻百日，以六十日為休息，一年足矣。」遂進兵。淵遣將帥步騎數萬屯遼隧，围堑二十餘里。諸將欲击之，懿曰：「此欲老吾兵，攻之正墮其計。此王邑所以恥過崑陽也。彼大眾在此，巢穴空虛。直抵襄平，出其不意，破之必矣。」乃多張旗幟，欲出其南，賊盡銳赴之。懿潛濟以出其北，弃賊直趨襄平；賊將戰败，懿围襄平。諸將請攻之，懿不聽。陳珪曰：「昔攻上庸，旬日之半破堅城，斬孟達。今日遠來，而更安缓，愚竊惑之。」懿曰：「達眾少而食支一年；吾將士四倍於達而糧不淹月，以一月较一年，安可不速？以四击一，正令失半而克，猶當為之。是以不計死傷，而計糧也。今賊眾我寡，賊飢我飽，而雨水乃爾，攻具不設，促之何為？自發京師，不忧賊攻，但忧賊走。今賊糧垂盡，而围落未合，掠其牛馬，抄其樵采，此故驅之走也。夫兵者诡道，善因事变。賊凭恃其眾，故雖飢困，不肯束手，當示無能以安之。若求小利而驚之，非計也。」既而雨霁，造攻具攻之，矢石如雨，糧盡窘急，人相食，乃使其將王健、柳甫乞降，請解围，當君臣面縛，懿〔不許，〕皆斬之。淵突围而走，懿复追及梁水上殺之，遼地悉平。","sortOrder":25},
  {"id":"s_work_bckl_8_26","chapterId":"ch_work_bckl_8","text":"〈避戰〉第七十九","sortOrder":26},
  {"id":"s_work_bckl_8_27","chapterId":"ch_work_bckl_8","text":"凡戰，若敵強我弱，敵初來氣銳，我之势弱，難以相持，且當避之，伺其疲敝而击之，則勝。法曰：「避其銳氣，击其惰歸。」","sortOrder":27},
  {"id":"s_work_bckl_8_28","chapterId":"ch_work_bckl_8","text":"漢靈帝中平六年，涼州賊王國围陳仓，以皇甫嵩讨之。董卓請速進，嵩曰：「百戰百勝，不如不戰而屈之。是以善用兵者，先為不可勝，以待敵之可勝。陳仓雖小，城〔守〕固備，未易拔。王國雖強，攻陳仓不下，其眾必疲，疲而击之，全勝之道也。」國攻之，終不拔，其眾疲敝解去。嵩進兵追击之。卓曰：「〔不可。兵法：〕窮寇勿迫，歸眾勿遏。」嵩曰：「不然。〔前吾不击，避其銳也；今而击之，待其衰也。所击疲師，非歸眾也。國眾且走，莫有斗志。以整击亂，非窮寇也。〕」遂獨追击而破之。卓由是有慚色。","sortOrder":28},
  {"id":"s_work_bckl_8_29","chapterId":"ch_work_bckl_8","text":"〈围戰〉第八十","sortOrder":29},
  {"id":"s_work_bckl_8_30","chapterId":"ch_work_bckl_8","text":"凡围戰之道，围其四面，須开一角，以示生路，使敵戰不堅，則城可拔，軍可破。法曰：「围師必闕。」","sortOrder":30},
  {"id":"s_work_bckl_8_31","chapterId":"ch_work_bckl_8","text":"漢末，曹操围壶關，攻之不拔。操曰：「城拔，皆坑之。」連月不下。曹仁言於曹操曰：「围城必示活門，所以开其生路也。今公告之必坑，使人人自為守。且城固而糧多，攻之則士卒傷，守之則延日久。今钝兵堅城下，攻必死之敵，非良策也。」操從之，乃拔其城。","sortOrder":31},
  {"id":"s_work_bckl_8_32","chapterId":"ch_work_bckl_8","text":"〔《百戰奇略》卷八終〕","sortOrder":32},
  {"id":"s_work_bckl_9_1","chapterId":"ch_work_bckl_9","text":"卷之九","sortOrder":1},
  {"id":"s_work_bckl_9_2","chapterId":"ch_work_bckl_9","text":"〈聲戰〉第八十一","sortOrder":2},
  {"id":"s_work_bckl_9_3","chapterId":"ch_work_bckl_9","text":"凡戰，所謂聲者，張虛聲也。聲東而击西，聲彼而击此，使敵人不知其所備，則我所攻者，乃敵人所不守也。法曰：「善攻者，敵不知其所守。」","sortOrder":3},
  {"id":"s_work_bckl_9_4","chapterId":"ch_work_bckl_9","text":"後漢建武五年，耿弇與張步相拒，步使其弟藍將精兵二萬守西安，諸郡太守合萬餘人守臨淄，相去四十餘里。弇進兵畫中，居二城之間。视西安城小而堅，且藍兵又精；臨淄雖大而易攻，乃敕諸將會後五日攻西安。藍聞之，日夜為備。至期夜半，弇敕諸將皆蓐食，會明，至臨淄。護軍荀梁等爭之，以為宜速攻西安。弇曰：「〔不然。〕西安聞吾欲攻之，日夜備守；臨淄出其不意，至必驚扰，攻之，則一日可拔。拔臨淄則西安孤，張藍與步阻絕，必自亡去，所謂击一而得二者也。若攻西安，不卒下，頓兵堅城，死傷必多。縱能拔之，藍帥兵奔還臨淄，併兵合势，觀人虛實。吾深入敵地，後無轉输，旬日之間，不戰而困。諸君之言，未見其宜。」遂攻臨淄，半日拔之，入據其城。張藍聞之，果將兵亡去。","sortOrder":4},
  {"id":"s_work_bckl_9_5","chapterId":"ch_work_bckl_9","text":"〈和戰〉第八十二","sortOrder":5},
  {"id":"s_work_bckl_9_6","chapterId":"ch_work_bckl_9","text":"凡與敵戰，必先遣使約和。敵雖許诺，言語不一。因其懈怠，選銳卒以击之，其軍可败。法曰：「無約而請和者，謀也。」","sortOrder":6},
  {"id":"s_work_bckl_9_7","chapterId":"ch_work_bckl_9","text":"秦末，天下兵起。沛公西入武關，欲以二萬人击秦峣下軍，張良曰：「秦兵尚強，未可輕。聞其將多屠、贾子，易以利動。願沛公且留壁，使人先行，為五萬人具食，且日益張旗幟為疑兵，而使郦生持寶啖秦將。」秦將果叛，欲連和。沛公欲聽之，良曰：「此獨其將欲叛耳，恐士卒不從，不從必危，不如因其懈击之。」沛公乃引兵出击秦軍，大破之。","sortOrder":7},
  {"id":"s_work_bckl_9_8","chapterId":"ch_work_bckl_9","text":"〈受戰〉第八十三","sortOrder":8},
  {"id":"s_work_bckl_9_9","chapterId":"ch_work_bckl_9","text":"凡戰，若敵眾我寡，暴來围我，須相察眾寡、虛實之形，不可輕易遁去，恐為尾击。當圓陣外向，受敵之围，雖有缺處，我自塞之，以堅士卒心。四面奋击，必獲其利。法曰：「敵若眾，則相眾而受敵。」","sortOrder":9},
  {"id":"s_work_bckl_9_10","chapterId":"ch_work_bckl_9","text":"《北史》：魏普泰元年，高歡讨併州刺史爾朱兆。孝武帝永熙元年春，拔鄴。爾朱光自長安，兆自併州，度律自洛陽，仲遠自東郡，同會於鄴，眾二十萬，挟漳水而軍。歡出頓紫陌，馬不滿三千，步不滿三萬。乃於韓陵為圓陣，連牛驢以塞歸路，〔於是〕將士皆為必死，選精銳步騎從中出，四面击之，大破兆等。","sortOrder":10},
  {"id":"s_work_bckl_9_11","chapterId":"ch_work_bckl_9","text":"〈降戰〉第八十四","sortOrder":11},
  {"id":"s_work_bckl_9_12","chapterId":"ch_work_bckl_9","text":"凡戰，若敵人來降，必要察其真伪。遠明斥候，日夜設備，不可怠忽。嚴令偏裨，整兵以待之，則勝，不然則败。法曰：「受降如受敵。」","sortOrder":12},
  {"id":"s_work_bckl_9_13","chapterId":"ch_work_bckl_9","text":"後漢建安二年，曹操讨張繡於宛，降之。〔繡〕既而悔恨复叛，袭击曹操軍，殺曹操長子昂、〔弟子安民〕，操中流矢，師還舞陰。繡將騎來，操击破之。繡奔穰，與劉表合。操謂諸將曰：「吾降繡，失在不便取质，以致如此。〔吾知所以败。〕諸將觀之，自今以後，不复败矣。」","sortOrder":13},
  {"id":"s_work_bckl_9_14","chapterId":"ch_work_bckl_9","text":"〈天戰〉第八十五","sortOrder":14},
  {"id":"s_work_bckl_9_15","chapterId":"ch_work_bckl_9","text":"凡欲興師動眾，伐罪弔民，必任天時。乃君暗政亂，兵驕民困，放逐賢人，誅殺無辜，旱蝗冰雹，敵國有此，舉兵攻之，無有不勝。法曰：「順天時而製征讨。」","sortOrder":15},
  {"id":"s_work_bckl_9_16","chapterId":"ch_work_bckl_9","text":"北齊，後主緯，隆化元年，擢用邪佞：陆令萱、和士开、高阿那肱、穆提婆、韓長鸞等，宰製天下，陳德信、邓長、何洪珍參預機權。各領親党，升擢非次，官由财進，獄以賂成，亂政害人，遂致旱魃、水潦、寇盜併起；又猜嫌諸王，皆無罪受損，丞相斛律光及弟荆山公羨，併無罪受誅。漸見覆弱之萌，俄觀土崩之势。周武帝乘此，一舉而滅之。","sortOrder":16},
  {"id":"s_work_bckl_9_17","chapterId":"ch_work_bckl_9","text":"〈人戰〉第八十六","sortOrder":17},
  {"id":"s_work_bckl_9_18","chapterId":"ch_work_bckl_9","text":"凡戰，所謂人者，推人士而破妖祥也。行軍之际，或枭集牙旗，或杯酒变血，或麾杆毀折，唯主將决之。若以順讨逆，以直伐曲，以賢击愚，皆無疑也。法曰：「禁祥去疑，至死無所之。」","sortOrder":18},
  {"id":"s_work_bckl_9_19","chapterId":"ch_work_bckl_9","text":"唐武德六年，辅公佑反，詔趙郡王李孝恭等讨之。將發，與將士宴集，命取水，忽变為血，在座皆失色，孝恭自若曰：「〔禍福無門，唯人所召。〕毋疑，此乃公佑授首之征也。」遂飲而盡之，眾心為安。先是，賊將拒险邀戰，孝恭堅壁不出，以奇兵絕其糧道。賊飢，夜薄李營，孝恭堅臥不動。明日，以羸兵扣賊營挑戰，別選騎裨以待。俄而羸兵却，賊追北且嚣，遇祖尚，薄戰，遂败。趙郡王乘勝破其別陣，辅公佑窮走，追騎生擒之〔，江南悉平〕。","sortOrder":19},
  {"id":"s_work_bckl_9_20","chapterId":"ch_work_bckl_9","text":"〈難戰〉第八十七","sortOrder":20},
  {"id":"s_work_bckl_9_21","chapterId":"ch_work_bckl_9","text":"凡為將之道，要在甘苦共眾。如遇危险之地，不可舍眾而自全，不可臨難而苟免，護衛周旋，同其生死。如此，則三軍之士豈忘己哉？法曰：「見危難，無忘其眾。」","sortOrder":21},
  {"id":"s_work_bckl_9_22","chapterId":"ch_work_bckl_9","text":"魏，曹操征孫權還，〔使〕張遼、樂進、李典將七千餘人屯合肥。操征張魯，教與護軍薛悌書，題其函曰：「敵至乃發。」俄而，權帥眾围合肥，乃發此教曰：「若孫權至者，張、李將軍出戰、樂將軍守城，護軍勿與戰。」諸將皆疑，遼曰：「公遠征在外，比敵至此，破我必矣，是以指教。及其未合，逆击之，折其盛势，以安眾心，然後可守也。勝負之機，在此一舉，諸君何疑？」李典意與遼同。於是，遼夜募敢從〔之士〕，得八百人，椎牛享士，明日大戰。平旦，遼披甲出戰，先登陷陣，殺賊數十人，斬二將，大呼自名，冲陣至權麾下。權大驚，眾未知所以，走登高。權以長戟自守，遼叱權下，權不敢動〔，望見遼所將眾少〕，乃聚兵围遼數重，遼左右突围，直前急击，围开，遼將麾下數十人得出，餘眾呼號曰：「將軍弃舍我耶？」遼复入围，拔出餘眾，權軍無敢當者。自旦至日中，吳人奪氣。遼〔還〕修守備，眾心乃安，〔諸將〕悅服。權守合肥旬日，城不得拔，乃退。遼率諸將追击，幾獲權。","sortOrder":22},
  {"id":"s_work_bckl_9_23","chapterId":"ch_work_bckl_9","text":"〈易戰〉第八十八","sortOrder":23},
  {"id":"s_work_bckl_9_24","chapterId":"ch_work_bckl_9","text":"凡攻戰之法，從易者勝敵。敵若屯備數處，必有強弱眾寡。我可遠其強而攻其弱，避其眾而击其寡，則無不勝。法曰：「善戰者，勝於易勝者也。」","sortOrder":24},
  {"id":"s_work_bckl_9_25","chapterId":"ch_work_bckl_9","text":"《北史》：周武帝〔將〕伐齊之河陽，〔謀及臣下〕，宇文弼〔進策〕曰：「〔今之用兵，須擇其地。〕河陽要冲，精兵所聚，盡力攻围，恐難得志。〔如臣所見，〕彼汾之曲，城小山平，攻之易拔。」武帝不納，師竟無功。〔建德五年，大舉伐齊，卒用計。後終於平齊。〕","sortOrder":25},
  {"id":"s_work_bckl_9_26","chapterId":"ch_work_bckl_9","text":"〈餌戰〉第八十九","sortOrder":26},
  {"id":"s_work_bckl_9_27","chapterId":"ch_work_bckl_9","text":"凡戰，所謂餌者，非謂兵者置毒於飲食，但以利誘之，皆為餌兵也。如交鋒之际，或弃牛馬，或遺财物，或舍辎重，切不可取，取之必败。法曰：「餌兵勿食。」","sortOrder":27},
  {"id":"s_work_bckl_9_28","chapterId":"ch_work_bckl_9","text":"漢獻帝建安五年，袁紹遣兵攻白馬，操击破之，斬其將顏良。遂解白馬之围，徙其民〔循河〕而西。紹渡河追之，軍至延津南。操勒兵駐營南坡下，令騎解鞍放馬。是時，白馬辎重就道。諸將以為敵騎多，不如還保營。荀攸曰：「此所謂餌兵，如之何去之！」紹騎將文丑與劉備將五六千騎前後至。諸將曰：「可上馬。」操曰：「未也。」有頃，騎至稍多，或分趣辎重。操曰：「可矣。」乃皆上馬。〔時騎不滿六百，遂〕縱〔兵〕击，大破之，〔斬丑〕。","sortOrder":28},
  {"id":"s_work_bckl_9_29","chapterId":"ch_work_bckl_9","text":"〈離戰〉第九十","sortOrder":29},
  {"id":"s_work_bckl_9_30","chapterId":"ch_work_bckl_9","text":"凡與敵戰，可密候鄰國君臣交接有隙，乃遣諜者以間之。彼若猜貳，我以精兵乘之，必得所欲。法曰：「親而離之。」","sortOrder":30},
  {"id":"s_work_bckl_9_31","chapterId":"ch_work_bckl_9","text":"戰國，周赧王三十一年，燕上將樂毅併將秦、魏、韓、趙之師伐齊，破之，泯王出奔於莒。燕軍聞齊王在莒，合兵攻之。楚將淖齒將兵救齊。因為齊相，欲與燕將分齊地，乃執王數其罪而誅之。复堅守莒城、即墨以拒燕兵，數月不下。樂毅併围之，即墨大夫戰死，城中推田单為將軍。頃之，〔燕〕昭王薨，惠王立，為太子時與毅有隙。田单聞之，乃縱反間曰：「樂毅與燕新王有隙，畏誅，欲連兵王齊，齊人未附，故且缓攻即墨以待其事。齊人唯恐他將之來，即墨殘矣。」燕王以為然，乃使騎劫代毅。毅遂奔趙，燕將士由是不和。单乃诈以卒為神師而祀之，列火牛陣，大破燕軍；复齊七十餘城，迎襄王自莒入臨淄。","sortOrder":31},
  {"id":"s_work_bckl_9_32","chapterId":"ch_work_bckl_9","text":"〔《百戰奇略》卷九終〕","sortOrder":32},
  {"id":"s_work_bckl_10_1","chapterId":"ch_work_bckl_10","text":"卷之十","sortOrder":1},
  {"id":"s_work_bckl_10_2","chapterId":"ch_work_bckl_10","text":"〈疑戰〉第九十一","sortOrder":2},
  {"id":"s_work_bckl_10_3","chapterId":"ch_work_bckl_10","text":"凡與敵對壘，我欲袭敵，須丛草雜木，多張旗幟，以為人屯。使敵備東，而击其西，則必勝。或我欲退，伪為虛陣，設留而退，敵必不敢追我。法曰：「眾草多障者，疑也。」","sortOrder":3},
  {"id":"s_work_bckl_10_4","chapterId":"ch_work_bckl_10","text":"《北史》：周武帝東征，以宇文憲為前鋒，守雀鼠穀。帝親臨围晉州，齊主聞晉州被围，亦自來援。時陳王純屯千里径，大將軍永昌公椿屯雞栖原，大將軍宇文盛守汾水關，併受憲節度。〔憲〕密謂椿曰：「兵者，诡道。汝今為營，不須張幕，可伐柏為庵，示有所處。〔令〕兵去之後，賊至猶疑。」時齊主分兵〔萬人〕向千里径，又遣眾出汾水關，自帥大軍與椿對。椿告齊兵急，憲自往救之。會軍败，齊追逐，師夜引還。齊人果以柏庵為帳幕之備，遂不敢進。翌日始悟。","sortOrder":4},
  {"id":"s_work_bckl_10_5","chapterId":"ch_work_bckl_10","text":"〈窮戰〉第九十二","sortOrder":5},
  {"id":"s_work_bckl_10_6","chapterId":"ch_work_bckl_10","text":"凡戰，如我眾敵寡，彼必畏我軍势，不戰而遁，切勿追之，蓋物極則反也。宜整兵缓追，則勝。法曰：「窮寇勿迫。」","sortOrder":6},
  {"id":"s_work_bckl_10_7","chapterId":"ch_work_bckl_10","text":"漢，趙充國讨先零羌，兵至羌虜所。羌久屯聚，懈弛，望見大軍，弃辎重，欲渡湟水。道隘狹，充國徐行驅之。或曰：「逐利行遲。」充國曰：「此窮寇，不可迫也。缓之則走不顧，急之則還死戰。」諸校皆曰：「善。」羌赴水溺死者數百，餘皆奔潰。","sortOrder":7},
  {"id":"s_work_bckl_10_8","chapterId":"ch_work_bckl_10","text":"〈風戰〉第九十三","sortOrder":8},
  {"id":"s_work_bckl_10_9","chapterId":"ch_work_bckl_10","text":"凡與敵戰，若遇風順，致势而击之；若遇風逆，出不意而捣之，則無有不勝。法曰：「風順，致势而從之；風逆，堅陣以待之。」","sortOrder":9},
  {"id":"s_work_bckl_10_10","chapterId":"ch_work_bckl_10","text":"《五代史》：晉北面行營都招讨使杜重威等，與契丹戰於陽城，為虜所围，而軍中無水，穿井辄崩；又東北風大起，虜順風縱火，扬尘以助其势。軍士皆憤怒，大呼曰：「都招讨何以用兵，令士卒枉死！」諸將請戰，杜重威曰：「候風少缓，徐觀可否。」〔馬步都監〕李守貞曰：「風沙之內，彼眾我寡，莫测多少，惟力戰者勝，此風力助我也。」即呼曰：「諸軍齊击賊！」〔馬軍左厢都排陣使〕張彦泽召諸將問計，或曰：「虜得風势，宜待風回。」彦泽亦以為然。〔馬軍〕右厢副〔陣〕使藥元福謂曰：「今軍飢渴已甚，待風回，吾屬皆為虜矣！且敵謂我不能逆風以戰，宜出其不意急击之。此诡道也。」〔馬步左右厢都排陣使〕符彦卿等乃將精騎，奋力击之，逐北二十餘里。契丹主奚車走十餘里，追兵击之，得一橐駝，乘之遁去。晉軍乃〔退保〕定〔州〕。","sortOrder":10},
  {"id":"s_work_bckl_10_11","chapterId":"ch_work_bckl_10","text":"〈雪戰〉第九十四","sortOrder":11},
  {"id":"s_work_bckl_10_12","chapterId":"ch_work_bckl_10","text":"凡與敵相攻，若雨雪不止，视敵不備，可潛兵击之，其势可破。法曰：「攻其所不戒。」","sortOrder":12},
  {"id":"s_work_bckl_10_13","chapterId":"ch_work_bckl_10","text":"唐遣唐邓節度使李愬讨吳元濟。先是愬遣將將二千餘騎巡邏，遇賊將丁士良，與戰，擒之。士良，元濟驍將，常為東邊患。眾請刳其心，愬許之。士良無懼色，遂命解其縛，士良請盡死以報其德，愬署為捉生將。士良言於愬曰：「吳秀琳據文城柵，為賊左臂，官軍不敢近者，有陳光洽為之主謀也。然光洽勇而輕，好自出戰，請為擒之，則秀琳自降矣。」鐵文及光洽被執，秀琳果降。愬延秀琳問計，秀琳答曰：「將軍必欲破賊，非得李佑不可。」佑，賊健將也，有勇略，守興桥柵，每戰常輕官軍，時率眾割麥於野。愬遣史用誠以壮士三百伏林中，用誠誘而擒之以歸。將士爭請殺之，愬獨待以客禮，時复與語，諸將不悅。愬力不能獨完，乃械送佑之京師。先密奏曰：「若殺佑，則無成功。」詔以佑還愬，愬見大喜，署為兵馬使，令佩刀出入帳中。始定破蔡之計，令佑以突將三千為前鋒，李忠義副之；愬與監軍將三千為中軍；李進誠以三千殿為後軍，令曰：「但東行！」〔行〕六十里，夜，至張柴村，盡殺其戍卒。敕士少休，令士卒食幹糧，整羁靮、鞍鎧、弓刃。時大雪，旗旆折裂，人馬冻死者相望，人人自謂必死。諸校請所之，愬曰：「入蔡州，取吳元濟。」眾皆失色，相泣曰：「果落李佑奸計。」然畏愬，莫敢违。夜半，雪愈盛。分輕兵斷賊朗山之援，又斷洄曲及諸道桥梁。行七十里至懸瓠城。城旁皆鹅鶩池，愬令击之以亂〔軍〕聲。初，蔡人拒命，官軍凡三十餘年不能至其城下，故蔡人皆不為備。佑等攀城先登，眾從之。殺守門者，而留击柝者，納其眾城中。雞鳴雪止，遂執元濟，槛送京師，而淮西悉平矣。","sortOrder":13},
  {"id":"s_work_bckl_10_14","chapterId":"ch_work_bckl_10","text":"〈養戰〉第九十五","sortOrder":14},
  {"id":"s_work_bckl_10_15","chapterId":"ch_work_bckl_10","text":"凡與敵戰，若我軍曾經挫衄，須審察士卒之氣。氣盛，則激励再戰；氣衰，則且養氣，待其可用而使之。法曰：「謹養勿勞，併氣積力。」","sortOrder":15},
  {"id":"s_work_bckl_10_16","chapterId":"ch_work_bckl_10","text":"秦始皇問李信曰：「吾欲取荆，度用幾何人？」對曰：「不過二十萬人。」及問王翦，曰：「非六十萬人不可。」王曰：「將軍老矣！何怯也！」乃命信及蒙恬將二十萬人伐荆。翦因不用，遂謝病歸頻陽。信〔攻平舆〕，蒙恬〔攻寢〕，大破之。〔信又攻鄢郢，破之。〕乃引兵西，與蒙恬會城父。荆人因隨之，三日不頓舍，大败信軍，入兩壁，殺七都尉，信奔還。王怒，自至頻陽見王翦，強起之。對曰：「老臣悖亂，大王必不得已用臣，非六十萬人不可。」王從之。翦遂將兵，王送至灞上。荆人聞之，悉兵以御翦。翦堅壁不戰，日休士卒，洗沐而善飲食撫循之，與士卒同甘苦。久之，問軍中戲乎？對曰：「方投石超距。」翦曰：「可用矣。」荆人既不得戰，乃引而東。翦追击，大破之。至蘄南，殺其將軍項燕，荆兵遂败走，翦乘勝略定城邑。","sortOrder":16},
  {"id":"s_work_bckl_10_17","chapterId":"ch_work_bckl_10","text":"〈畏戰〉第九十六","sortOrder":17},
  {"id":"s_work_bckl_10_18","chapterId":"ch_work_bckl_10","text":"凡與敵戰，軍中有畏怯者，鼓之不進，未聞金先退，須擇而殺之，以戒其眾。若三軍之士，人人皆懼，則不可加誅戮。須假之以顏色，示以不畏；說之以利害，喻以不死，則眾心自安。法曰：「執戮禁畏。太畏則勿殺戮，示之以顏色，告之以所生。」","sortOrder":18},
  {"id":"s_work_bckl_10_19","chapterId":"ch_work_bckl_10","text":"《南史》：陳武帝讨王僧辯，先召文育與謀。時僧辯婿杜龛據吳興，兵甚眾。武帝密令陳倩速還長城，立柵備之。龛遣將杜泰乘虛掩至。將士相视失色，倩言笑自若，部分益明，於是眾心乃定。","sortOrder":19},
  {"id":"s_work_bckl_10_20","chapterId":"ch_work_bckl_10","text":"〈書戰〉第九十七","sortOrder":20},
  {"id":"s_work_bckl_10_21","chapterId":"ch_work_bckl_10","text":"凡與敵對壘，不可令軍士通家書，親戚往來；恐言語不一，眾心疑惑。法曰：「信問通，則心有所恐；親戚往來，則心有所恋。」","sortOrder":21},
  {"id":"s_work_bckl_10_22","chapterId":"ch_work_bckl_10","text":"蜀將關羽屯江陵，吳以呂蒙代魯肅屯陆口。蒙初至，外倍修恩德，與羽結好。後蒙袭收公安、南郡，而蜀將皆降於蒙。蒙入據城，得羽將士家屬，皆撫慰，令軍卒不得幹歷人家，有所取求。蒙麾下士，與蒙同汝南人，取民一笠，以覆官鎧；雖公，蒙猶以為犯軍令，不可以乡里故废法，乃泣而斬之。於是，軍中震栗，道不拾遺。蒙旦暮使親近存恤耆老，問所不足，疾病者給医藥，飢寒者與衣糧。羽還，在道，每使人相問，蒙則厚遇之，周遊城中，家家致問，〔或手書示信〕。羽人還，私相參問，鹹贺家門無恙，相待過於平時，故羽士卒皆無斗志。會權又至，羽〔自知孤窮，乃走麥城〕，西至漳乡，眾皆降，羽被殺。","sortOrder":22},
  {"id":"s_work_bckl_10_23","chapterId":"ch_work_bckl_10","text":"〈变戰〉第九十八","sortOrder":23},
  {"id":"s_work_bckl_10_24","chapterId":"ch_work_bckl_10","text":"凡兵家之法，要在應变，好在知兵，舉動必先料敵。敵無变動，則待之；乘其有变，隨而應之，乃利。法曰：「能因敵变化而取勝者，謂之神。」","sortOrder":24},
  {"id":"s_work_bckl_10_25","chapterId":"ch_work_bckl_10","text":"五代梁末，魏博兵亂，贺德倫降晉。莊宗入魏〔州〕，梁將劉鄩乃軍於莘縣，增壘浚池，自莘至河，筑甬道输餉。梁帝詔鄩出戰。〔奏〕曰：「晉兵未易击，俟彼進取，苟得機便，豈敢坐滋患害？」帝又遣使問以决勝之策，對曰：「臣無奇謀，但人給十斛糧，盡皆破敵。」帝怒曰：「將軍留米將療飢耶？」又遣使督戰。鄩謂諸校曰：「大將专征，君命有所不受。臨敵製变，安可預謀。今揣彼自氣盛，難可輕克，諸君以為如何？」眾皆欲戰，鄩默然。〔他日，〕乃复召諸將列軍門，人給河水一杯，因命飲之。眾未测其意，或飲或辭。鄩曰：「一杯之難若是，滔滔河流可盡乎？」眾皆失色。時莊宗以兵壓鄩營，亦不出。帝又數遣人促之，鄩以萬人薄其營，俘獲甚眾。少頃，晉兵既至，鄩退，复戰於故元城。莊宗與李嗣源、李存審夹击，梁兵大败。","sortOrder":25},
  {"id":"s_work_bckl_10_26","chapterId":"ch_work_bckl_10","text":"〈好戰〉第九十九","sortOrder":26},
  {"id":"s_work_bckl_10_27","chapterId":"ch_work_bckl_10","text":"夫兵者，凶器也；戰者，逆德也。實不獲已而用之。不可以國之大、民之眾，盡銳征伐，爭戰不止，終致败亡，悔無所追。然兵猶火也，弗戢，將有自焚之患；黷武窮兵，禍不旋踵。法曰：「國雖大，好戰必亡。」","sortOrder":27},
  {"id":"s_work_bckl_10_28","chapterId":"ch_work_bckl_10","text":"隋之煬帝，國非不大，民非不眾，嗜武好戰，日尋幹戈，征伐不休，及事变兵败遼城，禍起萧牆，豈不為後世笑乎？吁，為人君者，可不慎哉！","sortOrder":28},
  {"id":"s_work_bckl_10_29","chapterId":"ch_work_bckl_10","text":"〈忘戰〉第一百","sortOrder":29},
  {"id":"s_work_bckl_10_30","chapterId":"ch_work_bckl_10","text":"凡安不忘危，治不忘亂，聖人之深誡也。天下無事，不可废武，慮有弗庭，無以捍御。必須內修文德，外嚴武備，懷柔遠人，戒不虞也。四時講武之禮，所以示國不忘戰。不忘戰者，教民不離乎習兵也。法曰：「天下雖安，忘戰必危。」","sortOrder":30},
  {"id":"s_work_bckl_10_31","chapterId":"ch_work_bckl_10","text":"唐玄宗時，承平日久，毀戈牧馬，罢將銷兵，國不知備，民不知戰。及安史之亂，仓卒变生於不圖，文士不足以為將，市人不足以為戰，而神器幾危，舊物幾失。吁，戰豈可忘乎哉！","sortOrder":31},
  {"id":"s_work_bckl_10_32","chapterId":"ch_work_bckl_10","text":"〔《百戰奇略》卷十終〕","sortOrder":32},
];

